// ===== Codeware `#176` (catálogo exaustivo, `App/UI/WidgetInputService.hpp`) — 2026-08-12,
// round 10 (agente offline dedicado). `IsCharacterInput`/`ToCharacter` são a metade de
// `WidgetInputService` que NÃO depende de nenhum endereço nativo — a fonte real
// (`WidgetInputService.cpp`) mostra que `IsCharacterInput(EInputKey)` é 100% comparação de
// ORDINAL (zero chamada C++/RTTI), e `ToCharacter` só chama Win32 (`GetKeyboardState`+
// `ToUnicode`) DEPOIS de passar por `IsCharacterInput` — a peça que genuinamente precisa do
// endereço Mac é só o HOOK (`Raw::inkSystem::ProcessCharacterEvent`, dispatch real de
// evento), que fica de fora (RE nunca feita, zero símbolo/string achado em varreduras
// anteriores desta sessão pra clusters `ink*` equivalentes — mesma categoria XL de `#100`/
// `InkSystem::Get()`).
//
// Achado-chave REUSADO (já confirmado nesta mesma base de código, `cw-rawinput-realname`,
// 2026-07-18): pra letras/dígitos/espaço, o valor NUMÉRICO de `EInputKey`
// (`redscript-src/orphans.script:3223`) já É o código ASCII do caractere (`IK_Space=32`,
// `IK_0..IK_9=48..57`, `IK_A..IK_Z=65..90`) — zero tabela necessária pra esses. Os símbolos
// de pontuação (`IK_Semicolon..IK_Tilde=186..192`, `IK_LeftBracket..IK_SingleQuote=219..222`,
// mesmos ranges do `IsCharacterInput` real) e o teclado numérico (`IK_NumPad0..IK_NumSlash=
// 96..111`) usam uma tabela ESTÁTICA US-QWERTY — DIVERGÊNCIA HONESTA vs. o `ToUnicode` real do
// Windows (que respeita o layout/locale configurado do usuário; aqui é sempre US-QWERTY, sem
// consciência de Caps Lock persistente — `shift` é o único modificador suportado, como
// parâmetro explícito em vez de ler `GetKeyboardState` real).
fn is_character_input_key(key: i32) -> bool {
    key == 32 // IK_Space
        || (48..=57).contains(&key) // IK_0..IK_9
        || (65..=90).contains(&key) // IK_A..IK_Z
        || (96..=111).contains(&key) // IK_NumPad0..IK_NumSlash
        || (186..=192).contains(&key) // IK_Semicolon..IK_Tilde
        || (219..=222).contains(&key) // IK_LeftBracket..IK_SingleQuote
}

/// Tabela US-QWERTY estática (ver nota grande acima pra divergência documentada). `Separator`
/// (`IK_Separator=108`, tecla numérica rara/dependente de locale mesmo no Win32 real) mapeia
/// pra vírgula por convenção — nunca confirmado contra hardware real, decisão consciente.
fn to_character_key(key: i32, shift: bool) -> String {
    if !is_character_input_key(key) {
        return String::new();
    }
    let ch: char = match key {
        32 => ' ',
        48..=57 => {
            if shift {
                [')', '!', '@', '#', '$', '%', '^', '&', '*', '('][(key - 48) as usize]
            } else {
                (b'0' + (key - 48) as u8) as char
            }
        }
        65..=90 => key as u8 as char, // já é ASCII maiúsculo (achado-chave reusado)
        96..=105 => (b'0' + (key - 96) as u8) as char, // IK_NumPad0..9
        106 => '*',  // IK_NumStar
        107 => '+',  // IK_NumPlus
        108 => ',',  // IK_Separator (divergência, ver nota da função)
        109 => '-',  // IK_NumMinus
        110 => '.',  // IK_NumPeriod
        111 => '/',  // IK_NumSlash
        186 => if shift { ':' } else { ';' },
        187 => if shift { '+' } else { '=' },
        188 => if shift { '<' } else { ',' },
        189 => if shift { '_' } else { '-' },
        190 => if shift { '>' } else { '.' },
        191 => if shift { '?' } else { '/' },
        192 => if shift { '~' } else { '`' },
        219 => if shift { '{' } else { '[' },
        220 => if shift { '|' } else { '\\' },
        221 => if shift { '}' } else { ']' },
        222 => if shift { '"' } else { '\'' },
        _ => return String::new(),
    };
    ch.to_string()
}

#[cfg(test)]
mod widgetinputservice_tests {
    use super::{is_character_input_key, to_character_key};

    #[test]
    fn letters_digits_space_are_character_input() {
        assert!(is_character_input_key(32)); // Space
        assert!(is_character_input_key(48)); // '0'
        assert!(is_character_input_key(57)); // '9'
        assert!(is_character_input_key(65)); // 'A'
        assert!(is_character_input_key(90)); // 'Z'
        assert!(!is_character_input_key(0)); // IK_None
        assert!(!is_character_input_key(27)); // IK_Escape
        assert!(!is_character_input_key(136)); // IK_Pad_A_CROSS (gamepad, não char)
    }

    #[test]
    fn punctuation_and_numpad_ranges_are_character_input() {
        assert!(is_character_input_key(186)); // Semicolon
        assert!(is_character_input_key(192)); // Tilde
        assert!(is_character_input_key(219)); // LeftBracket
        assert!(is_character_input_key(222)); // SingleQuote
        assert!(is_character_input_key(96)); // NumPad0
        assert!(is_character_input_key(111)); // NumSlash
        assert!(!is_character_input_key(193)); // Mouse4, fora dos 2 ranges
    }

    #[test]
    fn to_character_matches_ascii_for_letters_digits_space() {
        assert_eq!(to_character_key(32, false), " ");
        assert_eq!(to_character_key(48, false), "0");
        assert_eq!(to_character_key(57, false), "9");
        assert_eq!(to_character_key(65, false), "A");
        assert_eq!(to_character_key(90, false), "Z");
    }

    #[test]
    fn to_character_shifted_digits_give_symbols() {
        assert_eq!(to_character_key(49, true), "!"); // Shift+1
        assert_eq!(to_character_key(48, true), ")"); // Shift+0
        assert_eq!(to_character_key(56, true), "*"); // Shift+8
    }

    #[test]
    fn to_character_punctuation_shifted_and_unshifted() {
        assert_eq!(to_character_key(186, false), ";");
        assert_eq!(to_character_key(186, true), ":");
        assert_eq!(to_character_key(191, false), "/");
        assert_eq!(to_character_key(191, true), "?");
        assert_eq!(to_character_key(192, false), "`");
        assert_eq!(to_character_key(192, true), "~");
    }

    #[test]
    fn to_character_non_character_key_is_empty() {
        assert_eq!(to_character_key(27, false), ""); // Escape
        assert_eq!(to_character_key(0, false), ""); // None
    }
}

unsafe extern "C" fn tramp_is_character_input(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let args = rtti::read_params_consuming(current_native_func(), frame);
    let key = args.first().map(|(v, _)| *v as i32).unwrap_or(0);
    let ok = is_character_input_key(key);
    crate::log(&format!("[widgetinput] BwmsIsCharacterInput({key}) -> {ok}"));
    write_bool_ret(out, ok);
}

unsafe extern "C" fn tramp_to_character_key(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let args = rtti::read_params_consuming(current_native_func(), frame);
    let key = args.first().map(|(v, _)| *v as i32).unwrap_or(0);
    let shift = args.get(1).map(|(v, _)| *v != 0).unwrap_or(false);
    let s = to_character_key(key, shift);
    crate::log(&format!("[widgetinput] BwmsToCharacterKey({key}, shift={shift}) -> '{s}'"));
    write_cstring_inline_ret(out, &s);
}

