unsafe extern "C" fn tramp_refl_class_get_name(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let args = rtti::read_params_consuming(current_native_func(), frame);
    let cls = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    // CClass+0x18 = name (CName) — mesmo campo que TODA forja deste arquivo escreve
    // (`wr_u64(mem, 0x18, cname(new_name))`), lido aqui na direção inversa.
    let h = if rtti::sane(cls) { rd_u64(cls, 0x18) } else { 0 };
    write_uint_ret(out, h, 8);
}
unsafe extern "C" fn tramp_refl_class_get_parent(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let args = rtti::read_params_consuming(current_native_func(), frame);
    let cls = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let parent = if rtti::sane(cls) { rd_u64(cls, 0x10) } else { 0 };
    write_uint_ret(out, parent, 8);
}
unsafe extern "C" fn tramp_refl_class_get_property(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let args = rtti::read_params_consuming(current_native_func(), frame);
    let cls = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let hash = args.get(1).map(|(v, _)| *v).unwrap_or(0);
    let name = crate::cname::resolve_cname(hash);
    let prop = if rtti::sane(cls) { rtti::find_property_in_class(cls, &name) } else { std::ptr::null_mut() };
    write_uint_ret(out, prop as u64, 8);
}
unsafe extern "C" fn tramp_refl_class_get_property_count(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let args = rtti::read_params_consuming(current_native_func(), frame);
    let cls = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let n = if rtti::sane(cls) { rtti::class_own_properties(cls).len() as u32 } else { 0 };
    write_uint_ret(out, n as u64, 4);
}
unsafe extern "C" fn tramp_refl_class_get_property_by_index(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let args = rtti::read_params_consuming(current_native_func(), frame);
    let cls = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let idx = args.get(1).map(|(v, _)| *v as i32).unwrap_or(-1);
    let mut prop: *mut c_void = std::ptr::null_mut();
    if rtti::sane(cls) && idx >= 0 {
        let props = rtti::class_own_properties(cls);
        if let Some(p) = props.get(idx as usize) {
            prop = *p;
        }
    }
    write_uint_ret(out, prop as u64, 8);
}
unsafe extern "C" fn tramp_refl_class_get_function(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let args = rtti::read_params_consuming(current_native_func(), frame);
    let cls = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let hash = args.get(1).map(|(v, _)| *v).unwrap_or(0);
    let name = crate::cname::resolve_cname(hash);
    let f = if rtti::sane(cls) {
        rtti::resolve_in_class(cls, &name).map(|rf| rf.func).unwrap_or(std::ptr::null_mut())
    } else {
        std::ptr::null_mut()
    };
    write_uint_ret(out, f as u64, 8);
}
unsafe extern "C" fn tramp_refl_prop_get_name(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let args = rtti::read_params_consuming(current_native_func(), frame);
    let prop = args.first().map(|(v, _)| *v as *const c_void).unwrap_or(std::ptr::null());
    // CProperty+0x08 = name (CName) — layout já documentado/usado em `find_prop_exact`/`props_array`.
    let h = if rtti::sane(prop as *mut c_void) { rd_u64(prop, 0x08) } else { 0 };
    write_uint_ret(out, h, 8);
}
unsafe extern "C" fn tramp_refl_prop_get_value_float(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let args = rtti::read_params_consuming(current_native_func(), frame);
    let obj = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let prop = args.get(1).map(|(v, _)| *v as *const c_void).unwrap_or(std::ptr::null());
    let v = if rtti::sane(obj) && !prop.is_null() { rtti::prop_get_f32(prop, obj) } else { f32::NAN };
    if !out.is_null() {
        core::ptr::write_unaligned(out as *mut u32, v.to_bits());
    }
}
unsafe extern "C" fn tramp_refl_prop_set_value_float(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let args = rtti::read_params_consuming(current_native_func(), frame);
    let obj = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let prop = args.get(1).map(|(v, _)| *v as *const c_void).unwrap_or(std::ptr::null());
    let raw = args.get(2).map(|(v, _)| *v).unwrap_or(0);
    let value = f32::from_bits(raw as u32);
    let ok = rtti::sane(obj) && !prop.is_null();
    if ok {
        rtti::prop_set_f32(prop, obj, value);
    }
    write_bool_ret(out, ok);
}
unsafe extern "C" fn tramp_refl_prop_get_value_bool(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let args = rtti::read_params_consuming(current_native_func(), frame);
    let obj = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let prop = args.get(1).map(|(v, _)| *v as *const c_void).unwrap_or(std::ptr::null());
    let v = rtti::sane(obj) && !prop.is_null() && rtti::prop_get_bool(prop, obj);
    write_bool_ret(out, v);
}
unsafe extern "C" fn tramp_refl_prop_set_value_bool(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let args = rtti::read_params_consuming(current_native_func(), frame);
    let obj = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let prop = args.get(1).map(|(v, _)| *v as *const c_void).unwrap_or(std::ptr::null());
    let value = args.get(2).map(|(v, _)| v & 0xff != 0).unwrap_or(false);
    let ok = rtti::sane(obj) && !prop.is_null();
    if ok {
        rtti::prop_set_bool(prop, obj, value);
    }
    write_bool_ret(out, ok);
}
unsafe extern "C" fn tramp_refl_func_get_name(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let args = rtti::read_params_consuming(current_native_func(), frame);
    let func = args.first().map(|(v, _)| *v as *const c_void).unwrap_or(std::ptr::null());
    // CBaseFunction+0x10 = shortName (CName) — mesmo campo que `resolve_in_class` casa por nome.
    let h = if rtti::sane(func as *mut c_void) { rd_u64(func, 0x10) } else { 0 };
    write_uint_ret(out, h, 8);
}
/// `ReflectionFunc.Call(func, obj)` — chamada SEM ARGS (mesma receita de `BwmsCallMethod`, só que
/// aqui o método já veio de um `GetFunction`/`GetClass(...).GetFunction` anterior em vez de
/// resolvido por nome na hora). Retorno truncado pra `Bool` (primeiros 4 bytes != 0) — chamar com
/// ARGS/retorno tipado arbitrário é `cw-variant-marshalling`, bloqueado (sem atalho achado).
unsafe extern "C" fn tramp_refl_func_call(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let args = rtti::read_params_consuming(current_native_func(), frame);
    let func = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let obj = args.get(1).map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let mut ok = false;
    if rtti::sane(func) && rtti::sane(obj) {
        let rf = rtti::ResolvedFn { func, ret_type: rtti::fn_ret_type(func), is_static: false };
        ok = rtti::call_func(&rf, obj, &[]).is_some();
    }
    crate::log(&format!("[refl] BwmsReflFuncCall(func={func:p}, obj={obj:p}) ok={ok}"));
    write_bool_ret(out, ok);
}
unsafe extern "C" fn tramp_refl_enum_get_value(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let args = rtti::read_params_consuming(current_native_func(), frame);
    let en = args.first().map(|(v, _)| *v as *const c_void).unwrap_or(std::ptr::null());
    let hash = args.get(1).map(|(v, _)| *v).unwrap_or(0);
    let name = crate::cname::resolve_cname(hash);
    // Mesmo layout de `rtti::resolve_enum_value` (hashList@0x28/count@0x30/valueList@0x38), só que
    // ptr-based (o caller já tem o CEnum* de um `GetEnum` anterior, não o nome do tipo).
    let mut val = 0u64;
    if rtti::sane(en as *mut c_void) {
        let hp = rd_u64(en, 0x28) as *const u8;
        let n = rd_u64(en, 0x30) as u32; // só os 4 baixos importam; leitura larga é inofensiva (campo é u32)
        let n = n & 0xFFFF_FFFF;
        let vp = rd_u64(en, 0x38) as *const u8;
        let mh = cname(&name);
        if !hp.is_null() && !vp.is_null() && n < 100_000 && crate::gum::is_readable(hp as *const c_void, n as usize * 8) {
            for i in 0..n as usize {
                if rd_u64(hp as *const c_void, i * 8) == mh {
                    val = rd_u64(vp as *const c_void, i * 8);
                    break;
                }
            }
        }
    }
    write_uint_ret(out, val, 8);
}

/// Registra as globais de `cw-reflection-class-api` (ver nota longa acima). Todas via
/// `register_argful_by_types`/`compose_params_from_types` — a mesma receita 100% provada de
/// `BwmsCallMethod`/`HashToName`/etc., generalizada. NADA disto foi testado num boot ainda.
/// Codeware `#197` (`ReflectionType.GetInnerType()`, 2026-08-10) — `BwmsGetInnerTypeName
/// (typeName: CName) -> CName`: resolve o IType por nome (mesmo `get_type` já usado por
/// `compose_params_from_types`), lê `innerType@+0x10` (campo de dado, sem risco de vtable-shift —
/// ver nota longa em `rtti::get_inner_type`), resolve o nome do tipo interno.
unsafe extern "C" fn tramp_refl_get_inner_type_name(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let args = rtti::read_params_consuming(current_native_func(), frame);
    let hash = args.first().map(|(v, _)| *v).unwrap_or(0);
    let name = crate::cname::resolve_cname(hash);
    let mut inner_hash: u64 = 0;
    if let Some(reg) = rtti::Registry::obtain() {
        let ty = get_type(&reg, &name);
        if rtti::sane(ty) {
            if let Some(inner) = rtti::get_inner_type(ty) {
                inner_hash = rtti::type_name_getname(inner);
            }
        }
    }
    let inner_name = crate::cname::resolve_cname(inner_hash);
    crate::log(&format!("[refl] BwmsGetInnerTypeName('{name}') -> '{inner_name}'"));
    write_uint_ret(out, inner_hash, 8);
}

