// ===== Codeware `#142` (`OpenWorldTracker`), mecanismo confirmado pelo item `#232`
// (`CATALOGO-EXAUSTIVO-CODEWARE.md`) — `MappinSystem.hpp` real:
//
//   namespace Raw::MappinSystem {
//   constexpr auto SetPoiMappinPhase = Core::RawVFunc</* addr = */ 0x1D0, void(uint32_t,
//       gamedataMappinPhase)>();
//   constexpr auto GetPoiMappinPhase = Core::RawVFunc</* addr = */ 0x3C8,
//       gamedataMappinPhase(uint32_t)>();
//   }
//
// São slots de VTABLE do `MappinSystem`/`IMappinSystem` (offset Windows já em BYTES, não
// índice) — NÃO `RawFunc`/`AddressLib` (hash de endereço), então não precisam de RE de
// endereço Mac nova, só do shift Itanium +0x08 já estabelecido neste projeto pra vtable de
// classe C++ real (2 dtors no Mac vs 1 no MSVC — `DATABASE.md`: "vtable macOS = +0x08 vs
// Windows (2 dtors Itanium)", confirmado repetidas vezes na sessão de 2026-08-12 e em vários
// outros ciclos — RED4ext.SDK/#63, ArchiveXL/#53, etc.). Mac `SetPoiMappinPhase` =
// `0x1D0 + 0x08 = 0x1D8`; Mac `GetPoiMappinPhase` = `0x3C8 + 0x08 = 0x3D0`.
//
// `MappinSystem` já é instanciável/acessível neste projeto (item `#78`/`GetAllMappins`,
// provado ao vivo 2026-08-11, via `GameInstance.GetMappinSystem(game) -> ref<MappinSystem>`,
// native VANILLA real) — reusado aqui: as 2 natives abaixo recebem o ponteiro de
// `MappinSystem` (mesmo `Arg::Handle`/1º-arg-raw-pointer já usado por dezenas de outras
// natives, ex. `tramp_entity_find_component_by_type` acima), lêem o 1º qword do objeto
// (vtable), aplicam o offset Mac, lêem o slot como ponteiro de função e chamam — sempre
// validando `crate::gum::is_readable` ANTES de dereferenciar qualquer ponteiro (o objeto em
// si via `rtti::sane`+leitura da vtable, a vtable antes de indexar o slot, o slot antes de
// ler o function pointer, e o function pointer antes de chamar). `gamedataMappinPhase`
// (`orphans.script:1328`, enum RTTI-visível real: CompletedPhase=0/DefaultPhase=1/
// DiscoveredPhase=2/UndiscoveredPhase=3/Count=4/Invalid=5) é passado/devolvido por VALOR
// como inteiro de 32 bits na ABI Itanium (mesma convenção já usada neste projeto pra todo
// enum nativo passado a native do motor — nenhuma indireção/ponteiro), então os 2 params
// nativos usam `u32` cru (o lado redscript converte `gamedataMappinPhase<->Int32` via
// `EnumInt`/cast, ver `.reds`).
const MAPPIN_SET_POI_PHASE_SLOT: usize = 0x1D0 + 0x08; // = 0x1D8
const MAPPIN_GET_POI_PHASE_SLOT: usize = 0x3C8 + 0x08; // = 0x3D0

type MappinSetPoiPhaseFn = unsafe extern "C" fn(*mut c_void, u32, u32);
type MappinGetPoiPhaseFn = unsafe extern "C" fn(*mut c_void, u32) -> u32;

/// Lê `vtbl_ptr+slot_off` como ponteiro de função, validando legibilidade em cada passo
/// (objeto -> vtable -> slot -> function pointer). `None` em qualquer falha — nunca
/// dereferencia um ponteiro não confirmado legível. Generalizado 2026-08-14 (era
/// `mappinsystem_vtbl_fn`, específico do MappinSystem) — mesmo idioma reusado agora também
/// pelo `CommunitySystem` (`#77`, ver bloco abaixo); qualquer objeto C++ real com vtable no
/// offset 0 pode usar, só muda `slot_off` (Windows+0x08, shift Itanium já estabelecido).
unsafe fn vtbl_slot_fn(obj: *mut c_void, slot_off: usize) -> Option<*const c_void> {
    if !rtti::sane(obj) || !crate::gum::is_readable(obj as *const c_void, 8) {
        return None;
    }
    let vtbl = (obj as *const u64).read_unaligned() as *const u8;
    if vtbl.is_null() || !crate::gum::is_readable(vtbl as *const c_void, slot_off + 8) {
        return None;
    }
    let slot_ptr = vtbl.add(slot_off) as *const u64;
    if !crate::gum::is_readable(slot_ptr as *const c_void, 8) {
        return None;
    }
    let fp = slot_ptr.read_unaligned() as *const c_void;
    if fp.is_null() || !crate::gum::is_readable(fp, 4) {
        return None;
    }
    Some(fp)
}

/// `BwmsMappinSystemSetPoiPhase(sys: ref<MappinSystem>, journalPath: Uint32, phase: Int32) -> Void`
/// — chama `MappinSystem::SetPoiMappinPhase(journalPath, phase)` via slot de vtable Mac
/// `0x1D8` (ver nota grande acima). MUTA estado real de mappin de quest — nunca chamado
/// automaticamente por nenhum smoke test deste projeto.
unsafe extern "C" fn tramp_mappinsystem_set_poi_phase(_c: *mut c_void, frame: *mut c_void, _out: *mut c_void, _rt: i64) {
    let args = rtti::read_params_consuming(current_native_func(), frame);
    let sys = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let journal_path = args.get(1).map(|(v, _)| *v as u32).unwrap_or(0);
    let phase = args.get(2).map(|(v, _)| *v as u32).unwrap_or(0);
    match vtbl_slot_fn(sys, MAPPIN_SET_POI_PHASE_SLOT) {
        Some(fp) => {
            let f: MappinSetPoiPhaseFn = core::mem::transmute(fp);
            f(sys, journal_path, phase);
            crate::log(&format!(
                "[mappinsystem] BwmsMappinSystemSetPoiPhase(sys={sys:p}, journalPath={journal_path:#x}, phase={phase}) chamado via vtbl+{MAPPIN_SET_POI_PHASE_SLOT:#x}"
            ));
        }
        None => crate::log(&format!(
            "[mappinsystem] BwmsMappinSystemSetPoiPhase: sys={sys:p} inválido/vtable+{MAPPIN_SET_POI_PHASE_SLOT:#x} ilegível — NÃO chamado"
        )),
    }
}

/// `BwmsMappinSystemGetPoiPhase(sys: ref<MappinSystem>, journalPath: Uint32) -> Int32` —
/// chama `MappinSystem::GetPoiMappinPhase(journalPath)` via slot de vtable Mac `0x3D0`. Só
/// LEITURA — seguro pra smoke test automático (mesmo com `journalPath` fabricado; o pior
/// caso é devolver `Invalid`/`Count`, nunca muta nada).
unsafe extern "C" fn tramp_mappinsystem_get_poi_phase(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let args = rtti::read_params_consuming(current_native_func(), frame);
    let sys = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let journal_path = args.get(1).map(|(v, _)| *v as u32).unwrap_or(0);
    let mut phase: u32 = 5; // sentinela = gamedataMappinPhase.Invalid, só usado se a chamada não rolar
    let mut called = false;
    if let Some(fp) = vtbl_slot_fn(sys, MAPPIN_GET_POI_PHASE_SLOT) {
        let f: MappinGetPoiPhaseFn = core::mem::transmute(fp);
        phase = f(sys, journal_path);
        called = true;
    }
    crate::log(&format!(
        "[mappinsystem] BwmsMappinSystemGetPoiPhase(sys={sys:p}, journalPath={journal_path:#x}) -> {phase} (chamado={called}, vtbl+{MAPPIN_GET_POI_PHASE_SLOT:#x})"
    ));
    write_uint_ret(out, phase as u64, 4);
}

