unsafe fn register_mappinsystem_cooked_count_natives(reg: &Registry, proto: *mut c_void) {
    let params = compose_params_from_types(reg, &["handle:MappinSystem"]);
    let ok = params.1 == 1;
    if !ok {
        crate::log("[reg] register_mappinsystem_cooked_count_natives: compose_params_from_types falhou (handle:MappinSystem)");
    }
    let ok_mappin = ok
        && register_global_composed(
            reg,
            proto,
            params,
            "BwmsMappinSystemCookedMappinCount",
            "BwmsMappinSystemCookedMappinCount",
            tramp_mappinsystem_cooked_mappin_count,
        );
    let ok_multi = ok
        && register_global_composed(
            reg,
            proto,
            params,
            "BwmsMappinSystemCookedMultiMappinCount",
            "BwmsMappinSystemCookedMultiMappinCount",
            tramp_mappinsystem_cooked_multi_mappin_count,
        );
    let ok_poi = ok
        && register_global_composed(
            reg,
            proto,
            params,
            "BwmsMappinSystemCookedPoiCount",
            "BwmsMappinSystemCookedPoiCount",
            tramp_mappinsystem_cooked_poi_count,
        );
    crate::log(&format!(
        "[reg] register_all: archivexl-44-mappin-cooked-count BwmsMappinSystemCookedMappinCount={ok_mappin} BwmsMappinSystemCookedMultiMappinCount={ok_multi} BwmsMappinSystemCookedPoiCount={ok_poi}"
    ));
}

#[cfg(test)]
mod mappin_cooked_count_tests {
    use super::mappin_cooked_count_from_lens;

    #[test]
    fn none_means_uncached_sentinel_minus_one() {
        assert_eq!(mappin_cooked_count_from_lens(None), -1);
    }

    #[test]
    fn cached_but_empty_is_zero_not_sentinel() {
        assert_eq!(mappin_cooked_count_from_lens(Some((0, 0))), 0);
    }

    #[test]
    fn cached_with_entries_returns_size_not_capacity() {
        // size != capacity é o caso normal (array com folga reservada) — a função deve devolver
        // `size` (entradas REAIS), nunca `capacity` (espaço alocado).
        assert_eq!(mappin_cooked_count_from_lens(Some((7, 32))), 7);
    }

    #[test]
    fn large_size_fits_i32_without_overflow() {
        // `size` é u32; valores plausíveis de contagem de mappins nunca chegam perto de
        // i32::MAX, mas a conversão deve ser exata (sem saturar/errar) na faixa normal.
        assert_eq!(mappin_cooked_count_from_lens(Some((100_000, 100_000))), 100_000);
    }
}

// ---------------------------------------------------------------------------------------------
// Codeware `#77` (`CommunityWrapper`/`CommunitySystem`, sessão 2026-08-14, 100% offline) — fonte
// real (`enablers/Codeware/src/Red/CommunitySystem.hpp`): 7 dos 9 métodos de
// `Raw::CommunitySystem` são `Core::RawVFunc` — slot de VTABLE em bytes (Windows), NÃO
// `RawFunc`/`AddressLib` — mesma categoria zero-RE-de-endereço já usada pelo `MappinSystem`
// acima (`#142`/`#232`) e reconfirmada de novo aqui: só o shift Itanium Mac=Windows+0x08 já
// estabelecido neste projeto. `ActivateCommunity`@0x1B0/`DeactivateCommunity`@0x1B8/
// `SetCommunityPhase`@0x1C0/`ResetCommunity`@0x1C8/`ActivateSpawner`@0x1D8/
// `DeactivateSpawner`@0x1E0/`ResetSpawner`@0x1E8 (offsets Windows, bytes) → Mac = +0x08 cada.
// `GetCommunity`@0x228/`GetSpawner`@0x260 ficam DE FORA de propósito (achado do round 12 de
// 2026-08-12, catálogo item `#77`): devolvem `Red::WeakPtr<T>&` por out-param — tipo C++
// próprio do Codeware (`lib/Core/SharedPtr.hpp`, fora do escopo já catalogado desta sessão),
// ABI/layout nunca confirmados neste projeto — marshalling não-trivial, risco desproporcional
// pra uma rodada 100% offline sem boot pra verificar. As 7 funções ficam gated como MUTAÇÃO
// REAL DE MUNDO (ativam/desativam spawn de NPC/crowd) — nunca chamadas automaticamente por
// nenhum smoke test deste projeto (mesma disciplina já usada pro `SetPoiMappinPhase` acima).
//
// `CommunitySystem` já é acessível neste projeto via native VANILLA REAL confirmada em
// `redscript-src/orphans.script:11401` (`GameInstance.GetCommunitySystem(self) -> ref<
// CommunitySystem>`) — as 7 natives abaixo recebem o ponteiro já resolvido pelo mod (mesmo
// `Arg::Handle`/1º-arg-raw-pointer já usado por dezenas de outras natives, ex.
// `tramp_mappinsystem_*` acima), fazem o dispatch de vtable via `vtbl_slot_fn` (generalizado
// nesta mesma rodada, era `mappinsystem_vtbl_fn`) e chamam — sempre validando
// `crate::gum::is_readable` em cada passo antes de dereferenciar (idêntico ao MappinSystem).
// `aCommunityID`/`aSpawnerID` são `uint64_t` cru (o hash de um `EntityID`/`gameCommunityID`,
// já confirmado ser `{entityId: EntityID}` — `enablers/Codeware/scripts/Base/Imports/
// gameCommunityID.reds`); `CName` (nomes de entry/fase) é sempre 8 bytes/hash na ABI Itanium,
// mesma convenção já usada neste projeto pra todo CName passado a native do motor.
const COMMUNITY_ACTIVATE_SLOT: usize = 0x1B0 + 0x08;
const COMMUNITY_DEACTIVATE_SLOT: usize = 0x1B8 + 0x08;
const COMMUNITY_SET_PHASE_SLOT: usize = 0x1C0 + 0x08;
const COMMUNITY_RESET_SLOT: usize = 0x1C8 + 0x08;
const COMMUNITY_SPAWNER_ACTIVATE_SLOT: usize = 0x1D8 + 0x08;
const COMMUNITY_SPAWNER_DEACTIVATE_SLOT: usize = 0x1E0 + 0x08;
const COMMUNITY_SPAWNER_RESET_SLOT: usize = 0x1E8 + 0x08;

type CommunityIdEntryFn = unsafe extern "C" fn(*mut c_void, u64, u64);
type CommunitySetPhaseFn = unsafe extern "C" fn(*mut c_void, u64, u64, u64);
type CommunitySpawnerFn = unsafe extern "C" fn(*mut c_void, u64);

/// Núcleo comum das 4 natives `(sys, communityId, entryName)`. `label` só pro log.
unsafe fn community_id_entry_call(sys: *mut c_void, community_id: u64, entry_name: u64, slot: usize, label: &str) {
    match vtbl_slot_fn(sys, slot) {
        Some(fp) => {
            let f: CommunityIdEntryFn = core::mem::transmute(fp);
            f(sys, community_id, entry_name);
            crate::log(&format!(
                "[communitysystem] {label}(sys={sys:p}, communityId={community_id:#x}, entryName={entry_name:#x}) chamado via vtbl+{slot:#x}"
            ));
        }
        None => crate::log(&format!(
            "[communitysystem] {label}: sys={sys:p} inválido/vtable+{slot:#x} ilegível — NÃO chamado"
        )),
    }
}

/// Núcleo comum das 3 natives `(sys, spawnerId)`.
unsafe fn community_spawner_call(sys: *mut c_void, spawner_id: u64, slot: usize, label: &str) {
    match vtbl_slot_fn(sys, slot) {
        Some(fp) => {
            let f: CommunitySpawnerFn = core::mem::transmute(fp);
            f(sys, spawner_id);
            crate::log(&format!(
                "[communitysystem] {label}(sys={sys:p}, spawnerId={spawner_id:#x}) chamado via vtbl+{slot:#x}"
            ));
        }
        None => crate::log(&format!(
            "[communitysystem] {label}: sys={sys:p} inválido/vtable+{slot:#x} ilegível — NÃO chamado"
        )),
    }
}

unsafe fn read_args3(frame: *mut c_void) -> (u64, u64, u64) {
    let args = rtti::read_params_consuming(current_native_func(), frame);
    let a = args.first().map(|(v, _)| *v).unwrap_or(0);
    let b = args.get(1).map(|(v, _)| *v).unwrap_or(0);
    let c = args.get(2).map(|(v, _)| *v).unwrap_or(0);
    (a, b, c)
}

unsafe extern "C" fn tramp_community_activate(_c: *mut c_void, frame: *mut c_void, _out: *mut c_void, _rt: i64) {
    let (sys, cid, entry) = read_args3(frame);
    community_id_entry_call(sys as *mut c_void, cid, entry, COMMUNITY_ACTIVATE_SLOT, "BwmsCommunityActivate");
}
unsafe extern "C" fn tramp_community_deactivate(_c: *mut c_void, frame: *mut c_void, _out: *mut c_void, _rt: i64) {
    let (sys, cid, entry) = read_args3(frame);
    community_id_entry_call(sys as *mut c_void, cid, entry, COMMUNITY_DEACTIVATE_SLOT, "BwmsCommunityDeactivate");
}
unsafe extern "C" fn tramp_community_reset(_c: *mut c_void, frame: *mut c_void, _out: *mut c_void, _rt: i64) {
    let (sys, cid, entry) = read_args3(frame);
    community_id_entry_call(sys as *mut c_void, cid, entry, COMMUNITY_RESET_SLOT, "BwmsCommunityReset");
}
unsafe extern "C" fn tramp_community_set_phase(_c: *mut c_void, frame: *mut c_void, _out: *mut c_void, _rt: i64) {
    let func = current_native_func();
    let args = rtti::read_params_consuming(func, frame);
    let sys = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let cid = args.get(1).map(|(v, _)| *v).unwrap_or(0);
    let entry = args.get(2).map(|(v, _)| *v).unwrap_or(0);
    let phase = args.get(3).map(|(v, _)| *v).unwrap_or(0);
    match vtbl_slot_fn(sys, COMMUNITY_SET_PHASE_SLOT) {
        Some(fp) => {
            let f: CommunitySetPhaseFn = core::mem::transmute(fp);
            f(sys, cid, entry, phase);
            crate::log(&format!(
                "[communitysystem] BwmsCommunitySetPhase(sys={sys:p}, communityId={cid:#x}, entryName={entry:#x}, phaseName={phase:#x}) chamado via vtbl+{COMMUNITY_SET_PHASE_SLOT:#x}"
            ));
        }
        None => crate::log(&format!(
            "[communitysystem] BwmsCommunitySetPhase: sys={sys:p} inválido/vtable+{COMMUNITY_SET_PHASE_SLOT:#x} ilegível — NÃO chamado"
        )),
    }
}
unsafe extern "C" fn tramp_community_spawner_activate(_c: *mut c_void, frame: *mut c_void, _out: *mut c_void, _rt: i64) {
    let func = current_native_func();
    let args = rtti::read_params_consuming(func, frame);
    let sys = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let sid = args.get(1).map(|(v, _)| *v).unwrap_or(0);
    community_spawner_call(sys, sid, COMMUNITY_SPAWNER_ACTIVATE_SLOT, "BwmsCommunitySpawnerActivate");
}
unsafe extern "C" fn tramp_community_spawner_deactivate(_c: *mut c_void, frame: *mut c_void, _out: *mut c_void, _rt: i64) {
    let func = current_native_func();
    let args = rtti::read_params_consuming(func, frame);
    let sys = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let sid = args.get(1).map(|(v, _)| *v).unwrap_or(0);
    community_spawner_call(sys, sid, COMMUNITY_SPAWNER_DEACTIVATE_SLOT, "BwmsCommunitySpawnerDeactivate");
}
unsafe extern "C" fn tramp_community_spawner_reset(_c: *mut c_void, frame: *mut c_void, _out: *mut c_void, _rt: i64) {
    let func = current_native_func();
    let args = rtti::read_params_consuming(func, frame);
    let sys = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let sid = args.get(1).map(|(v, _)| *v).unwrap_or(0);
    community_spawner_call(sys, sid, COMMUNITY_SPAWNER_RESET_SLOT, "BwmsCommunitySpawnerReset");
}

// `GetCommunity` (Codeware `#77`, 2026-08-14, mesma sessão — slot que faltava nas 7 já
// implementadas acima). Fonte real (`enablers/Codeware/src/Red/CommunitySystem.hpp`):
//   GetCommunity@0x228 = void* (ICommunitySystem::*)(WeakPtr<Community>& aOut,
//                                                     const uint64_t& aCommunityID)
// Mac = Windows 0x228 + 0x08 (shift Itanium já estabelecido) = 0x230. **A SLOT em si está
// correta** — o crash real (2026-08-14 14:05, `Cyberpunk2077-2026-08-14-140515.ips`, thread
// `redDispatcher4`, `EXC_BAD_ACCESS`/`KERN_INVALID_ADDRESS at 0x4`) foi diagnosticado por
// disassembly REAL do binário Mac na região da falha (não suposição): a função que mora nesse
// slot (vmaddr estático `0x1014aca3c`, faulting insn em `0x1014acba8`) NÃO usa a ABI que o
// header do Codeware sugere (2 parâmetros por referência). O corpo real:
//   - `this+0x68`/`this+0x74` = ponteiro+contagem de um array ORDENADO de IDs (busca binária via
//     `0x101f05ce8`, um comparador TRIVIAL `cmp x0,x1; cset w0,lo; ret` — confirma que os 2
//     valores comparados são ESCALARES `uint64_t`, nunca deferenciados);
//   - `x1` (2º argumento) é usado DIRETO nessa comparação, sem NENHUM `ldr` — ou seja,
//     `aCommunityID` chega **por VALOR em x1**, não por ponteiro (diferente do que o header
//     documenta — o header descreve a assinatura C++ "de intenção", não necessariamente a ABI
//     exata desta build);
//   - o "não achado" cai no branch `mov x8,#0; b <store>` → `stp x8, xzr, [x20]`, onde `x20` foi
//     copiado de **x8 NA ENTRADA DA FUNÇÃO** (`mov x20, x8`, a 1ª instrução real do corpo) — x8
//     é o REGISTRADOR DE RESULTADO INDIRETO do ARM64 (AAPCS64/Itanium), usado quando o retorno é
//     um tipo C++ NÃO-TRIVIAL devolvido POR VALOR (`WeakPtr<Community>` tem dtor não-trivial,
//     `~WeakPtr(){DecWeakRef();}` — pela regra Itanium isso força sret INDEPENDENTE do tamanho).
//   O bug real: a implementação ANTERIOR chamava a função como `(this, *mut u8, *const u64)`
//   (x0=this, x1=ponteiro-pro-out-buf, x2=ponteiro-pro-id) — **nunca populava x8** (Rust/LLVM só
//   usa x8 automaticamente quando o TIPO DE RETORNO Rust em si precisa de sret — não é o caso
//   de um simples `*mut c_void`). x8 ficava com LIXO de chamadas anteriores (calhou em `4` nesse
//   boot) → a função salvava esse lixo em `x20` → `stp x8,xzr,[x20]` escrevia em `[0x4]` →
//   crash EXATO em `0x0000000000000004`, o mesmo endereço do relatório.
//
// **Fix (mesmo padrão `SretPad32` já provado ao vivo neste projeto pra exatamente este tipo de
// bug — ArchiveXL `axl-garment-apply`/`axl-inkspawner-apply`, 2026-07-29, ver `selftest.rs`):**
// declarar o retorno Rust como uma struct >16 bytes força o LLVM/aarch64 a usar sret de verdade
// (populando x8 sozinho, do jeito que o C++ real espera) — e passar `community_id` POR VALOR
// (não mais um ponteiro), batendo com o que o comparador provou. Isso elimina o out-buf de 16
// bytes por completo (não é mais necessário — o valor chega pronto no sret).
#[repr(C)]
struct CommunityWeakPtrSret {
    instance: u64,
    ref_count: u64,
    _pad: [u64; 2],
}
const COMMUNITY_GET_COMMUNITY_SLOT: usize = 0x228 + 0x08;
type CommunityGetFn = unsafe extern "C" fn(*mut c_void, u64) -> CommunityWeakPtrSret;

/// Núcleo: chama `GetCommunity(sys, communityId)` via vtable (ABI sret real, ver nota acima),
/// lê o `WeakPtr<Community>` cru devolvido (`{instance,refCount}`) e devolve `instance` (0 =
/// não achou/candidato inválido). LEITURA apenas contra o `CommunitySystem` real (não muta
/// nenhum estado de mundo) — mas É dispatch de vtable genuinamente novo, testado com cautela
/// (1 hash real + 1 fabricado, nunca em loop).
unsafe fn community_get_community(sys: *mut c_void, community_id: u64) -> u64 {
    match vtbl_slot_fn(sys, COMMUNITY_GET_COMMUNITY_SLOT) {
        Some(fp) => {
            let f: CommunityGetFn = core::mem::transmute(fp);
            let result = f(sys, community_id);
            let instance = result.instance;
            let refcount = result.ref_count;
            crate::log(&format!(
                "[communitysystem] BwmsCommunityGetCommunity(sys={sys:p}, communityId={community_id:#x}) -> instance={instance:#x} refCount={refcount:#x} via vtbl+{COMMUNITY_GET_COMMUNITY_SLOT:#x} (sret)"
            ));
            instance
        }
        None => {
            crate::log(&format!(
                "[communitysystem] BwmsCommunityGetCommunity: sys={sys:p} inválido/vtable+{COMMUNITY_GET_COMMUNITY_SLOT:#x} ilegível — NÃO chamado"
            ));
            0
        }
    }
}

/// `BwmsCommunityGetCommunity(sys: ref<CommunitySystem>, communityId: Uint64) -> Uint64` —
/// devolve o ponteiro `instance` do `WeakPtr<Community>` (0 = indefinido/não achado). `Uint64`
/// cru em vez de `wref<T>` forjado — mesma divergência de escopo já documentada pro resto do
/// item (nenhum tipo `Community`/`Spawner` foi forjado na RTTI, categoria de risco evitada de
/// propósito).
unsafe extern "C" fn tramp_community_get_community(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let func = current_native_func();
    let args = rtti::read_params_consuming(func, frame);
    let sys = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let cid = args.get(1).map(|(v, _)| *v).unwrap_or(0);
    let instance = community_get_community(sys, cid);
    write_uint_ret(out, instance, 8);
}

// `GetSpawner` (Codeware `#77`, 2026-08-14, mesma sessão — irmão de `GetCommunity`, fecha o
// item por completo, 9/9 slots de vtable). Fonte real
// (`enablers/Codeware/src/Red/CommunitySystem.hpp`):
//   GetSpawner@0x260 = void* (ICommunitySystem::*)(WeakPtr<Spawner>& aOut, uint64_t aSpawnerID)
// Mac = Windows 0x260 + 0x08 (mesmo shift Itanium já estabelecido pra esta classe) = 0x268.
// MESMA técnica exata que fechou `GetCommunity` acima (`CommunityWeakPtrSret`, sret real via
// struct >16 bytes — força o LLVM/aarch64 a popular x8 sozinho, do jeito que o C++ real espera
// pro retorno não-trivial de `WeakPtr<T>`, dtor não-trivial via regra Itanium). Diferença
// consciente vs `GetCommunity`: aqui o header já declara `aSpawnerID` como `uint64_t` PURO (não
// `const uint64_t&` como `aCommunityID` tinha) — bate direto com a ABI real confirmada por
// disassembly pro slot irmão (2º argumento por VALOR em x1, nunca por ponteiro), então passamos
// `spawner_id` por valor sem precisar re-confirmar via disassembly nova.
const COMMUNITY_GET_SPAWNER_SLOT: usize = 0x260 + 0x08;
type CommunityGetSpawnerFn = unsafe extern "C" fn(*mut c_void, u64) -> CommunityWeakPtrSret;

/// Núcleo: chama `GetSpawner(sys, spawnerId)` via vtable (ABI sret real, ver nota acima), lê o
/// `WeakPtr<Spawner>` cru devolvido (`{instance,refCount}`) e devolve `instance` (0 = não
/// achado/candidato inválido). LEITURA apenas contra o `CommunitySystem` real (não muta nenhum
/// estado de mundo).
unsafe fn community_get_spawner(sys: *mut c_void, spawner_id: u64) -> u64 {
    match vtbl_slot_fn(sys, COMMUNITY_GET_SPAWNER_SLOT) {
        Some(fp) => {
            let f: CommunityGetSpawnerFn = core::mem::transmute(fp);
            let result = f(sys, spawner_id);
            let instance = result.instance;
            let refcount = result.ref_count;
            crate::log(&format!(
                "[communitysystem] BwmsCommunityGetSpawner(sys={sys:p}, spawnerId={spawner_id:#x}) -> instance={instance:#x} refCount={refcount:#x} via vtbl+{COMMUNITY_GET_SPAWNER_SLOT:#x} (sret)"
            ));
            instance
        }
        None => {
            crate::log(&format!(
                "[communitysystem] BwmsCommunityGetSpawner: sys={sys:p} inválido/vtable+{COMMUNITY_GET_SPAWNER_SLOT:#x} ilegível — NÃO chamado"
            ));
            0
        }
    }
}

/// `BwmsCommunityGetSpawner(sys: ref<CommunitySystem>, spawnerId: Uint64) -> Uint64` — devolve
/// o ponteiro `instance` do `WeakPtr<Spawner>` (0 = indefinido/não achado). `Uint64` cru em vez
/// de `wref<T>` forjado — mesma divergência de escopo consciente já usada em `GetCommunity`
/// (nenhum tipo `Spawner` foi forjado na RTTI).
unsafe extern "C" fn tramp_community_get_spawner(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let func = current_native_func();
    let args = rtti::read_params_consuming(func, frame);
    let sys = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let sid = args.get(1).map(|(v, _)| *v).unwrap_or(0);
    let instance = community_get_spawner(sys, sid);
    write_uint_ret(out, instance, 8);
}

// `BwmsCommunityScanSpawners` (2026-08-14, continuação — retomada dedicada ao teste decisivo
// de `GetSpawner`). Achado da rodada anterior: os 3 hashes usados até agora (`realId1/2/3`,
// primeiros 3 do dump de 10254 do `save-parser`) são todos de COMUNIDADE (confirmados via
// `GetCommunity`), não de spawner. `save-parser/src/community.rs`/`CommunitySystemParser.cs`
// (fonte real WolvenKit, `WolvenKit.RED4/Save/Parser/CommunitySystemParser.cs`) confirma que o
// node `CommunitySystem` do save é uma ÚNICA lista sem distinção estrutural — o próprio campo
// da WolvenKit se chama `Unk_HashList` (nem os autores da ferramenta de referência sabem a
// semântica completa) — não existe uma 2ª lista separada de spawners pra extrair; extender o
// parser não teria o que achar de novo. Em vez disso, varre TODOS os 10254 hashes já
// extraídos contra os 2 métodos SÓ-LEITURA (`GetCommunity`/`GetSpawner`), embutidos aqui via
// `include_str!` (mesmo hash-set já provado seguro pros 3 primeiros, agora testado por
// completo) — procura um hash onde `GetCommunity==0` (não é comunidade) E `GetSpawner!=0`
// (É spawner), o sinal decisivo de um ID de spawner GENUÍNO. Read-only puro (nenhuma das duas
// funções muta estado de mundo), ~20K chamadas de vtable/binary-search triviais — negligível
// em tempo de CPU, mas loga só o RESUMO + até 20 exemplos de hit de spawner (evita inundar o
// log com 20 mil linhas).
// 🔴 2026-08-22 — as duas listas de hash deixaram de ser `include_str!`.
//
// Elas vinham dos SAVES DE UMA PESSOA (10254 e 10232 hashes extraídos de `AutoSave-5` e
// `EndGameSave-2` de uma partida específica) e eram embutidas no binário — inclusive no build
// PÚBLICO, onde somavam ~380 KB de dado que não era de quem instalou. Duas coisas erradas de
// uma vez: dado derivado do jogo viajando no pacote, e a varredura só fazendo sentido contra
// aquela partida.
//
// Agora a lista vem do save de QUEM ESTÁ JOGANDO, lida em runtime de um arquivo de texto
// (um hash `0x...` por linha). Gerar a lista do próprio save é trabalho do `save-parser` do
// projeto, offline e só-leitura. Sem o arquivo, o comando explica o que falta em vez de
// falhar calado.
fn community_hashes_de_arquivo(nome: &str) -> Result<String, String> {
    let home = std::env::var("HOME").map_err(|_| "HOME não definido".to_string())?;
    let caminho = std::path::Path::new(&home).join(nome);
    std::fs::read_to_string(&caminho).map_err(|e| {
        format!(
            "lista de hashes não encontrada em ~/{nome} ({e}). \
             Esta varredura roda contra os hashes de comunidade do SEU save — gere o arquivo \
             com o save-parser do projeto (um hash 0x... por linha) e rode de novo."
        )
    })
}

// `COMMUNITY_HASHES_ENDGAMESAVE2` (2026-08-14, continuação — teste contra OUTRO save, pedido
// explícito depois do achado NEGATIVO exaustivo contra AutoSave-5). `save-parser` rodado
// offline (sem boot, 100% read-only) contra os 44 saves em
// `~/Library/Application Support/CD Projekt Red/Cyberpunk 2077/saves/` achou que a GRANDE
// MAIORIA (`AutoSave-0`/`AutoSave-7`/`ManualSave-57`, testados) tem a MESMA lista EXATA de
// 10254 hashes que `AutoSave-5` (0 hashes de diferença — mesmo personagem/momento de progressão
// de mundo, saves múltiplos do mesmo ponto). Só a família `EndGameSave-*` (2/3, Jun-11, ponto de
// jogo MUITO mais avançado — fim de jogo) deu uma lista GENUINAMENTE DIFERENTE: 10232 hashes,
// sendo 13 exclusivos desta família (ausentes de `AutoSave-5`) e 35 hashes de `AutoSave-5`
// ausentes aqui — confirma que listas de save DIFERENTES realmente têm conteúdo diferente
// (não é bug do parser). `ManualSave-40` não tem `sav.dat` (pasta vestigial, só
// metadata+screenshot) — pulado. Lista completa (10232, não só os 13 exclusivos) embutida aqui
// pelo mesmo motivo do `AutoSave-5`: mesmo se um hash já testado como "comunidade" em
// `AutoSave-5` aparecer aqui também, rodar a varredura completa contra o `CommunitySystem` VIVO
// (que reflete o save que o autocontinue carregou nesta sessão de boot, presumivelmente ainda
// `AutoSave-5`) é o mesmo protocolo já usado — o teste decisivo é achar QUALQUER
// `GetCommunity==0 && GetSpawner!=0` em QUALQUER dos 2 datasets.
/// Arquivo padrão e alternativo, ambos no HOME de quem está jogando.
const COMMUNITY_HASHES_ARQUIVO: &str = ".bwms-community-hashes.txt";
const COMMUNITY_HASHES_ARQUIVO_ALT: &str = ".bwms-community-hashes-2.txt";

unsafe fn run_community_scan_spawners(sys: *mut c_void) -> String {
    match community_hashes_de_arquivo(COMMUNITY_HASHES_ARQUIVO) {
        Ok(lista) => run_community_scan_spawners_against(sys, &lista, "save-do-usuario"),
        Err(e) => format!("[communityscan] {e}"),
    }
}

/// Mesma varredura contra uma SEGUNDA lista — útil pra comparar dois pontos de progressão do
/// próprio jogador (a diferença entre saves distantes é o que torna a varredura informativa).
unsafe fn run_community_scan_spawners_endgamesave2(sys: *mut c_void) -> String {
    match community_hashes_de_arquivo(COMMUNITY_HASHES_ARQUIVO_ALT) {
        Ok(lista) => run_community_scan_spawners_against(sys, &lista, "save-do-usuario-2"),
        Err(e) => format!("[communityscan] {e}"),
    }
}

unsafe fn run_community_scan_spawners_against(sys: *mut c_void, hash_list: &str, label: &str) -> String {
    if sys.is_null() || !rtti::sane(sys) {
        return format!("[communityscan:{label}] sys inválido — abortado");
    }
    let mut community_only = 0usize;
    let mut spawner_only = 0usize;
    let mut both = 0usize;
    let mut neither = 0usize;
    let mut tested = 0usize;
    let mut spawner_examples: Vec<String> = Vec::new();

    for line in hash_list.lines() {
        let hex = line.trim().trim_start_matches("0x");
        if hex.is_empty() {
            continue;
        }
        let h = match u64::from_str_radix(hex, 16) {
            Ok(v) => v,
            Err(_) => continue,
        };
        tested += 1;

        let c = match vtbl_slot_fn(sys, COMMUNITY_GET_COMMUNITY_SLOT) {
            Some(fp) => {
                let f: CommunityGetFn = core::mem::transmute(fp);
                f(sys, h).instance
            }
            None => 0,
        };
        let s = match vtbl_slot_fn(sys, COMMUNITY_GET_SPAWNER_SLOT) {
            Some(fp) => {
                let f: CommunityGetSpawnerFn = core::mem::transmute(fp);
                f(sys, h).instance
            }
            None => 0,
        };

        match (c != 0, s != 0) {
            (true, true) => both += 1,
            (true, false) => community_only += 1,
            (false, true) => {
                spawner_only += 1;
                if spawner_examples.len() < 20 {
                    spawner_examples.push(format!("{h:#018x}(instance={s:#x})"));
                }
            }
            (false, false) => neither += 1,
        }
    }

    format!(
        "[communityscan:{label}] sys={sys:p} testados={tested} community_only={community_only} spawner_only={spawner_only} both={both} nenhum={neither} | spawner_examples=[{}]",
        spawner_examples.join(", ")
    )
}

/// `BwmsCommunityScanSpawners(sys: ref<CommunitySystem>) -> Void` — varredura em lote, ver nota
/// grande acima. Loga o resumo (contagens + até 20 hashes de spawner genuíno, se algum existir).
unsafe extern "C" fn tramp_community_scan_spawners(_c: *mut c_void, frame: *mut c_void, _out: *mut c_void, _rt: i64) {
    let func = current_native_func();
    let args = rtti::read_params_consuming(func, frame);
    let sys = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let summary = run_community_scan_spawners(sys);
    crate::log(&summary);
}

/// `BwmsCommunityScanSpawnersEndGame(sys: ref<CommunitySystem>) -> Void` — MESMO mecanismo de
/// `BwmsCommunityScanSpawners`, mas contra o hash-set extraído de `EndGameSave-2` (10232 hashes,
/// 13 exclusivos vs `AutoSave-5`, ver nota grande em `COMMUNITY_HASHES_ENDGAMESAVE2`). `sys` é o
/// `CommunitySystem` VIVO do save que o autocontinue carregou nesta sessão de boot (não muda —
/// só o conjunto de hashes testados contra ele muda), pedido explícito de testar contra "outros
/// saves" depois do resultado negativo exaustivo contra a lista de `AutoSave-5` sozinha.
unsafe extern "C" fn tramp_community_scan_spawners_endgamesave2(_c: *mut c_void, frame: *mut c_void, _out: *mut c_void, _rt: i64) {
    let func = current_native_func();
    let args = rtti::read_params_consuming(func, frame);
    let sys = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let summary = run_community_scan_spawners_endgamesave2(sys);
    crate::log(&summary);
}

