/// keytest: constrói KeyInputEvent com fixture + lê GetKey/GetAction (prova cw-event-target-classes).
pub unsafe fn run_keyinput_test(reg: &rtti::Registry) {
    let obj = rtti::new_object(reg, "KeyInputEvent");
    if obj.is_null() {
        crate::log("[keytest] new_object('KeyInputEvent') falhou — classe não registrada?");
        return;
    }
    if let Ok(mut states) = KEYINPUT_STATES.lock() {
        states.push((obj as usize, 2, 99, true, false, true));
    }
    let cls = rtti::class_of(obj);
    let key_val = rtti::resolve_in_class(cls, "GetKey")
        .and_then(|rf| rtti::call_func(&rf, obj, &[]))
        .map(|r| i32::from_le_bytes([r[0], r[1], r[2], r[3]]));
    let action_val = rtti::resolve_in_class(cls, "GetAction")
        .and_then(|rf| rtti::call_func(&rf, obj, &[]))
        .map(|r| i32::from_le_bytes([r[0], r[1], r[2], r[3]]));
    let ok = key_val == Some(99) && action_val == Some(2);
    crate::log(&format!(
        "[keytest] obj={obj:p} GetKey={key_val:?}(exp=99) GetAction={action_val:?}(exp=2) {}",
        if ok { ">>> CW-EVENT-TARGET-CLASSES PASS <<<" } else { "MISMATCH" }
    ));
}

/// entitytest: empurra handle no DynArray entity+0xA0 do player (prova cw-entity-builder).
pub unsafe fn run_entity_builder_test(player: *mut c_void) {
    if player.is_null() {
        crate::log("[entitytest] player nulo — precisa estar em gameplay");
        return;
    }
    let arr = (player as *mut u8).add(0xA0) as *mut c_void;
    if !crate::gum::is_readable(arr as *const c_void, 0x10) {
        crate::log("[entitytest] player+0xA0 (ComponentsStorage.components) ilegível");
        return;
    }
    let mut buf = [0u8; 16];
    rtti::make_handle(buf.as_mut_ptr() as *mut c_void, player);
    let inst = (buf.as_ptr() as *const u64).read_unaligned();
    let refc = (buf.as_ptr().add(8) as *const u64).read_unaligned();
    match dynarray_push_handle16(arr, inst, refc) {
        Some(slot) => crate::log(&format!(
            "[entitytest] BwmsEntityAddComponent: entity={player:p} component=self pushed slot={slot} @entity+0xA0 >>> CW-ENTITY-BUILDER PASS <<<"
        )),
        None => crate::log("[entitytest] BwmsEntityAddComponent: dynarray_push_handle16 falhou (alloc)"),
    }
}

/// axl-fullbody-torso (2026-08-07, cont.41): em vez de esperar um evento disparar pra um
/// componente de torso (3 candidatos já testados, todos silenciosos ou só-mundo — ver
/// `notes/GARMENT-APPEARANCE-COMPONENT-FACTS.md` §3), ENUMERA DIRETO os componentes reais do
/// player AGORA — mesmo offset GROUND-TRUTH já usado em `cw-entity-builder`
/// (`Entity+0x70(ComponentsStorage)+0x30(components) = Entity+0xA0`, `DynArray<Handle<
/// IComponent>>`: entries@+0x00/cap@+0x08/size@+0x0C, stride 16B `{instance,refcount}`).
/// Resolve a CClass* de `SkinnedMeshComponent` 1x via RTTI e compara por IGUALDADE DE PONTEIRO
/// contra `rtti::class_of()` de cada componente (evita precisar resolver nome de classe a
/// partir de CClass*, que este projeto não tem pronto) — leitura 100% observe-only, zero
/// mutação, seguro mesmo em produção. Reusa o mesmo par de offsets já confirmado no probe
/// `rebuild-proxy` (`enabled@+0x8b`, `res_ptr@+0x1f8`) pra cada instância achada.
pub unsafe fn run_enum_skinnedmesh(reg: &crate::rtti::Registry, player: *mut c_void) -> String {
    if player.is_null() || !crate::gum::is_readable(player as *const c_void, 0x10) {
        return "[enumcomp] player nulo/ilegível".to_string();
    }
    // Nome RTTI real confirmado neste projeto (selftest.rs, sondas de postload já provadas):
    // `entSkinnedMeshComponent` (prefixo `ent`, não o nome bare). `entGarmentSkinnedMeshComponent`
    // é a SUBCLASSE usada por peças de roupa/garment (torso é garment) — como pointer-equality
    // não pega subclasses, o match abaixo caminha a cadeia de PARENT de cada componente (mesmo
    // offset `cls+0x10` já usado em `rtti::class_of`/dump_class_funcs) até achar `target_cls` ou
    // chegar em null, cobrindo `entSkinnedMeshComponent` e QUALQUER subclasse dele (incl. Garment).
    let target_cls = reg.class_by_name("entSkinnedMeshComponent");
    if target_cls.is_null() {
        return "[enumcomp] classe 'entSkinnedMeshComponent' não achada no registry".to_string();
    }
    let arr = (player as *mut u8).add(0xA0) as *mut c_void;
    if !crate::gum::is_readable(arr as *const c_void, 0x10) {
        return "[enumcomp] player+0xA0 (ComponentsStorage.components) ilegível".to_string();
    }
    let entries = rd_u64(arr, 0x00) as *const u8;
    let size = core::ptr::read_unaligned((arr as *const u8).add(0x0C) as *const u32);
    if entries.is_null() || size == 0 || size > 4096 {
        return format!("[enumcomp] array inválido: entries={entries:p} size={size}");
    }
    let mut total = 0usize;
    let mut matched = 0usize;
    let mut out = format!("[enumcomp] player={player:p} target_cls(SkinnedMeshComponent)={target_cls:p} size={size}\n");
    for i in 0..size as usize {
        let slot = entries.add(i * 16);
        if !crate::gum::is_readable(slot as *const c_void, 16) {
            continue;
        }
        let inst = core::ptr::read_unaligned(slot as *const u64) as *mut c_void;
        if inst.is_null() {
            continue;
        }
        total += 1;
        let mut cls = crate::rtti::class_of(inst);
        let mut is_match = false;
        let mut depth = 0usize;
        while !cls.is_null() && depth < 32 {
            if cls == target_cls {
                is_match = true;
                break;
            }
            if !crate::gum::is_readable(cls as *const c_void, 0x18) {
                break;
            }
            cls = rd_u64(cls, 0x10) as *mut c_void; // parent CClass*
            depth += 1;
        }
        if is_match {
            matched += 1;
            let leaf_cls = crate::rtti::class_of(inst);
            let (enabled, res_ptr) = if crate::gum::is_readable(inst as *const c_void, 0x200) {
                let e = (inst as *const u8).add(0x8b).read_unaligned();
                let r = ((inst as *const u8).add(0x1f8) as *const u64).read_unaligned();
                (Some(e), Some(r))
            } else {
                (None, None)
            };
            out.push_str(&format!(
                "  #{matched} entSkinnedMeshComponent(ou subclasse) inst={inst:p} leaf_cls={leaf_cls:p} enabled={enabled:?} res_ptr={res_ptr:#x?}\n"
            ));
            // (cont.41): scan_cnames-lite nas instâncias DESABILITADAS (candidatas a "hide-in-fpp")
            // E também nas HABILITADAS cujo hash bate com candidatos de interesse específico
            // (ex. componente de pescoço FPP, já confirmado visível desde cont.33 — comparação
            // mais informativa que um componente habilitado genérico qualquer).
            let interesting_enabled = enabled == Some(1) && {
                let h = (inst as *const u8).add(0x40).cast::<u64>().read_unaligned();
                h == crate::cname::cname("n0_000_pma_base__fpp__neck")
                    || h == crate::cname::cname("neck")
            };
            if (enabled == Some(0) || interesting_enabled) && crate::gum::is_readable(inst as *const c_void, 0x90) {
                for off in (0x08..0x90usize).step_by(8) {
                    let w = (inst as *const u8).add(off).cast::<u64>().read_unaligned();
                    if w == 0 {
                        continue;
                    }
                    let name = crate::cname::resolve_cname(w);
                    if !name.is_empty() && name != "None" {
                        out.push_str(&format!(
                            "      scan +{off:#04x}={w:#018x} CName='{name}'\n"
                        ));
                    }
                }
            }
        }
    }
    out.push_str(&format!(
        "[enumcomp] total_componentes_lidos={total} SkinnedMeshComponent_achados={matched}"
    ));
    out
}

/// axl-attachment-apply / itens #40, #41, #54 (2026-08-19, continuação direta da manhã): dump
/// SOB DEMANDA (não gated a um firing do hook `EquipStart`) do array `unk90`+0xB0 do componente
/// `gameAttachmentSlots` do player — permite reler o estado ATUAL do array (ex. pós-`give`+
/// `equiprawv7`) sem precisar esperar um novo evento nativo. Mesma travessia de
/// `run_enum_skinnedmesh` (componentes reais em `player+0xA0`), procurando a classe
/// `gameAttachmentSlots` (nome RTTI real do header oficial, `game::AttachmentSlots::NAME`).
/// Confirma identidade por 2 sinais independentes: `class_by_name` bater E `IComponent::name`
/// (CName@+0x40) == `fnv1a64("AttachmentSlots")` — mesmo golden já usado no probe do hook.
/// Acha a instância REAL `gameAttachmentSlots` do `player` (mesma travessia de componentes já
/// usada por `run_enum_skinnedmesh`/`scan_attachslots_now`) — extraído como helper reusável pro
/// item #40/#41/#54 (composição pura de `IsSlotEmpty`/`IsSlotSpawning`, ver
/// [`attachslot_check_by_id`] abaixo). Confirma identidade por 2 sinais: `class_by_name` bater
/// E `IComponent::name`(CName@+0x40) == `fnv1a64("AttachmentSlots")`.
unsafe fn find_attachslots_component(reg: &crate::rtti::Registry, player: *mut c_void) -> Option<*mut c_void> {
    if player.is_null() || !crate::gum::is_readable(player as *const c_void, 0x10) {
        return None;
    }
    let mut target_cls = reg.class_by_name("gameAttachmentSlots");
    if target_cls.is_null() {
        target_cls = reg.class_by_name("AttachmentSlots");
    }
    if target_cls.is_null() {
        return None;
    }
    let arr = (player as *mut u8).add(0xA0) as *mut c_void;
    if !crate::gum::is_readable(arr as *const c_void, 0x10) {
        return None;
    }
    let entries = rd_u64(arr, 0x00) as *const u8;
    let size = core::ptr::read_unaligned((arr as *const u8).add(0x0C) as *const u32);
    if entries.is_null() || size == 0 || size > 4096 {
        return None;
    }
    for i in 0..size as usize {
        let slot = entries.add(i * 16);
        if !crate::gum::is_readable(slot as *const c_void, 16) {
            continue;
        }
        let inst = core::ptr::read_unaligned(slot as *const u64) as *mut c_void;
        if inst.is_null() {
            continue;
        }
        let mut cls = crate::rtti::class_of(inst);
        let mut is_match = false;
        let mut depth = 0usize;
        while !cls.is_null() && depth < 32 {
            if cls == target_cls {
                is_match = true;
                break;
            }
            if !crate::gum::is_readable(cls as *const c_void, 0x18) {
                break;
            }
            cls = rd_u64(cls, 0x10) as *mut c_void; // parent CClass*
            depth += 1;
        }
        if !is_match || !crate::gum::is_readable(inst as *const c_void, 0x120) {
            continue;
        }
        let name_hash = (inst as *const u8).add(0x40).cast::<u64>().read_unaligned();
        if name_hash != bwms_hashes::fnv1a64(b"AttachmentSlots") {
            continue;
        }
        return Some(inst);
    }
    None
}

pub unsafe fn scan_attachslots_now(reg: &crate::rtti::Registry, player: *mut c_void) -> String {
    let inst = match find_attachslots_component(reg, player) {
        Some(p) => p,
        None => return "[scanattach2] nenhuma instância 'gameAttachmentSlots' achada nos componentes do player".to_string(),
    };
    let arr1_ptr = (inst as *const u8).add(0xB0).cast::<u64>().read_unaligned();
    let arr1_capsize = (inst as *const u8).add(0xB8).cast::<u64>().read_unaligned();
    let arr1_cap = (arr1_capsize & 0xFFFF_FFFF) as u32;
    let arr1_size = (arr1_capsize >> 32) as u32;
    let mut out = format!(
        "[scanattach2] AttachmentSlots*={inst:p} array1@{arr1_ptr:#018x} cap={arr1_cap} size={arr1_size}\n"
    );
    for line in crate::selftest::dump_attachslotdata_candidate(arr1_ptr, arr1_cap, arr1_size) {
        out.push_str(&format!("  {line}\n"));
    }
    out
}

/// ArchiveXL `#40`/`#41`/`#54` (2026-08-19) — IMPLEMENTAÇÃO REAL de `IsSlotEmpty`/`IsSlotSpawning`
/// como COMPOSIÇÃO PURA (sem chamar a função nativa `Core::RawFunc<AttachmentSlots_IsSlotEmpty>`,
/// que nunca teve endereço Mac resolvido) — lê o campo certo do struct `AttachmentSlotData`
/// (`game::AttachmentSlotData`, `RED4ext.SDK/.../gameAttachmentSlotData.hpp`, 0x90 bytes,
/// CONFIRMADO ao vivo nesta sessão: `slotID`@0x00 bateu com 14/23 nomes reais `AttachmentSlots.*`
/// via `bwms_hashes::tweak_db_id`, e `itemObject.instance`@0x08 ficou não-nulo EXATAMENTE nos
/// slots que o outfit inicial do player realmente ocupa — Head/Eyes/Chest/Torso/RightArm/Legs/
/// UnderwearBottom/Feet — e zero nos vazios — WeaponRight/WeaponLeft/PersonalLink/Consumable/
/// Outfit —, `proofs/2026-08-19-archivexl-40-41-54-isslotempty-isslotspawning-composicao-*.log`).
///
/// Semântica: `IsSlotEmpty` = `itemObject.instance == 0` (nenhum item VISUAL anexado ao slot —
/// bate com o nome do campo real e com o padrão observado). `IsSlotSpawning` =
/// `spawningItemID.tdbid != 0` (campo dedicado do struct pra essa transição — nunca observado
/// `true` em nenhuma captura desta sessão porque é estado TRANSIENTE, mesma limitação já
/// documentada pra `TransactionSystem.IsSlotSpawningAnyItem` noutras sessões — a composição é
/// estruturalmente a leitura certa do campo certo, mesmo sem um positivo ao vivo capturado).
///
/// Devolve `None` se o componente/slot não foi achado (chamador decide o fallback).
pub unsafe fn attachslot_check_by_id(
    reg: &crate::rtti::Registry,
    player: *mut c_void,
    slot_tdbid: u64,
) -> Option<(bool /* is_empty */, bool /* is_spawning */, &'static str /* nome resolvido */)> {
    let inst = find_attachslots_component(reg, player)?;
    let arr1_ptr = (inst as *const u8).add(0xB0).cast::<u64>().read_unaligned();
    let arr1_capsize = (inst as *const u8).add(0xB8).cast::<u64>().read_unaligned();
    let arr1_cap = (arr1_capsize & 0xFFFF_FFFF) as u32;
    let arr1_size = (arr1_capsize >> 32) as u32;
    if arr1_ptr == 0 {
        return None;
    }
    let n = arr1_size.min(arr1_cap).min(64) as usize;
    for i in 0..n {
        let base = arr1_ptr as usize + i * 0x90;
        if !crate::gum::is_readable(base as *const c_void, 0x90) {
            continue;
        }
        let rd = |off: usize| ((base + off) as *const u64).read_unaligned();
        let this_slot_id = rd(0x00);
        if this_slot_id != slot_tdbid {
            continue;
        }
        let item_obj_instance = rd(0x08);
        let spawning_tdbid = rd(0x18);
        let is_empty = item_obj_instance == 0;
        let is_spawning = spawning_tdbid != 0;
        let name = crate::selftest::match_attachment_slot_name(this_slot_id);
        return Some((is_empty, is_spawning, name));
    }
    None
}

/// ArchiveXL `#40` (2026-08-19, continuação direta) — composição REAL da metade "extra-slots" de
/// `AttachmentExtension::OnAttachTPP` (Extension.cpp:140-185), usando o hook confirmado ao vivo
/// `TPP_ONATTACH_C2_VM` (2 disparos reais, padrão consistente com `OnAttach` genuíno, sessão de
/// hoje mais cedo) como gatilho. Reproduz fielmente a fonte C++ real (comentário na fonte):
///
/// `for slotID in {HeadSlot,FaceSlot}: subSlots = s_extraSlots[slotID]; for subSlotID in subSlots:`
/// `affectedAppearanceSlots.PushBack(subSlotID) se ainda não tiver; se slotData.itemObject, chama`
/// `RegisterAffectedItem(component, itemID, itemObject)`.
///
/// Peças usadas, TODAS já provadas nesta sessão/anteriores, ZERO endereço nativo novo:
/// - `TPPAffectedSlots={Head,Eyes}` — constante hardcoded (hash já conhecido).
/// - "extra slots via `.parentSlot`" — em vez de hookar `AttachmentSlots::InitializeSlots`
///   (endereço Mac desconhecido, gap SEPARADO) e manter um mapa `s_extraSlots` cacheado, fazemos a
///   MESMA pergunta on-demand pra cada slot REAL do player (via `find_attachslots_component`, já
///   provado ontem/hoje, item #54): `get_flat_tdbid(t, tweak_db_id_derive(slotID, ".parentSlot"))`
///   — leitura dinâmica de flat já provada (`tramp_get_flat_float`, TweakXL #43), mesma técnica.
///   Equivalente semântico exato (mesma pergunta, resolvida sob demanda em vez de cacheada).
/// - `FindSlotData(owner, slotID==subSlotID)` — em vez do vtable call nativo (endereço não
///   resolvido, e a predicate/lambda C++ não é chamável em ABI seguro do Rust sem RE nova), fazemos
///   a MESMA busca por composição pura: scan do array `AttachmentSlotData` real (já provado #54).
/// - `itemID = ItemObject::ItemID(itemObject).tdbid` — offset `0x288` (`Raw::ItemObject::ItemID`,
///   `enablers/ArchiveXL/src/Red/ItemObject.hpp`, campo de dado, confiança alta).
/// - `affectedAppearanceSlots.PushBack` — `dynarray_push_ptr` (já provado, usado por `AddTag`/etc.),
///   sobre o campo REAL `TPPRepresentationComponent+0xB0` (`DynArray<TweakDBID>`, offset CONFIRMADO
///   pelo header GERADO da reflection real do jogo — `TPPRepresentationComponent.hpp`).
///
/// **NÃO fecha o item**: `RegisterAffectedItem` (`Raw::TPPRepresentationComponent::RegisterAffectedItem`)
/// segue sem candidato de endereço Mac — quando um item é achado no sub-slot, é LOGADO mas NÃO
/// registrado via chamada nativa (a peça que faz a peça-visual aparecer/sumir em TPP não roda).
/// Achado OFFLINE decisivo desta mesma sessão (grep exaustivo em `tweakdbstr.kark`, 3.529.116
/// nomes conhecidos): ZERO record `AttachmentSlots.*` do jogo base (2.31) tem flat
/// `.parentSlot`/`.dependencySlots` definido — confirmado que `s_extraSlots` fica SEMPRE VAZIO pra
/// conteúdo vanilla (a feature só existe pra sub-slots que um MOD declare via `.xl`/TweakDB). Esta
/// função reconfirma isso AO VIVO por mecanismo INDEPENDENTE (lookup por-slot em vez de busca
/// global de nome).
pub unsafe fn onattachtpp_compose(reg: &crate::rtti::Registry, a_component: *mut c_void) -> String {
    if a_component.is_null() || !crate::gum::is_readable(a_component as *const c_void, 0xC0) {
        return "[axl-40-onattachtpp] aComponent inválido/ilegível, abortado".to_string();
    }
    let head = bwms_hashes::tweak_db_id("AttachmentSlots.Head");
    let eyes = bwms_hashes::tweak_db_id("AttachmentSlots.Eyes");

    let player = crate::current_player();
    let attach_inst = match find_attachslots_component(reg, player) {
        Some(p) => p,
        None => return "[axl-40-onattachtpp] AttachmentSlots do player não achado, abortado".to_string(),
    };
    let t = match crate::tweakdb_rt::singleton() {
        Some(s) => s,
        None => return "[axl-40-onattachtpp] TweakDB singleton indisponível, abortado".to_string(),
    };

    let arr1_ptr = (attach_inst as *const u8).add(0xB0).cast::<u64>().read_unaligned();
    let arr1_capsize = (attach_inst as *const u8).add(0xB8).cast::<u64>().read_unaligned();
    let arr1_cap = (arr1_capsize & 0xFFFF_FFFF) as u32;
    let arr1_size = (arr1_capsize >> 32) as u32;
    if arr1_ptr == 0 {
        return format!("[axl-40-onattachtpp] aComponent={a_component:p}: array de AttachmentSlotData vazio");
    }
    let n = arr1_size.min(arr1_cap).min(64) as usize;

    let mut found: Vec<(u64, u64, u64)> = Vec::new(); // (base_slot, sub_slot, item_obj_instance)
    let mut checked = 0usize;
    for i in 0..n {
        let base = arr1_ptr as usize + i * 0x90;
        if !crate::gum::is_readable(base as *const c_void, 0x90) {
            continue;
        }
        let rd = |off: usize| ((base + off) as *const u64).read_unaligned();
        let slot_id = rd(0x00);
        if slot_id == 0 {
            continue;
        }
        checked += 1;
        let parent_flat_id = bwms_hashes::tweak_db_id_derive(slot_id, ".parentSlot");
        if let Some(parent_val) = crate::tweakdb_rt::get_flat_tdbid(t, parent_flat_id) {
            if parent_val == head || parent_val == eyes {
                found.push((parent_val, slot_id, rd(0x08)));
            }
        }
    }

    let mut out = format!(
        "[axl-40-onattachtpp] aComponent={a_component:p} AttachmentSlots={attach_inst:p} slots_checados={checked} extra_slots_achados={}",
        found.len()
    );

    if found.is_empty() {
        out.push_str(" — ZERO extra-slots (esperado: nenhum record AttachmentSlots.* do jogo base tem .parentSlot; s_extraSlots morto pra conteúdo vanilla, confirmado offline+ao-vivo)");
        return out;
    }

    // Composição real: dedupe + PushBack em affectedAppearanceSlots@+0xB0 do TPPRepresentationComponent
    // (offset confirmado pelo header GERADO da reflection real do jogo).
    let aff_arr = (a_component as *mut u8).add(0xB0) as *mut c_void;
    for (base_slot, sub_slot, item_obj) in &found {
        out.push_str(&format!(
            "\n  extra_slot base={base_slot:#018x} sub={sub_slot:#018x} item_obj={item_obj:#018x}"
        ));
        let aff_entries = rd_u64(aff_arr, 0x00) as *const u8;
        let aff_size = core::ptr::read_unaligned((aff_arr as *const u8).add(0x0C) as *const u32);
        let mut already = false;
        if !aff_entries.is_null() {
            for j in 0..aff_size.min(4096) {
                let ev = (aff_entries.add(j as usize * 8) as *const u64).read_unaligned();
                if ev == *sub_slot {
                    already = true;
                    break;
                }
            }
        }
        if already {
            out.push_str(" (já em affectedAppearanceSlots, dedupe correto — nada escrito)");
        } else {
            match dynarray_push_ptr(aff_arr, *sub_slot) {
                Some(idx) => out.push_str(&format!(" -> PushBack em affectedAppearanceSlots[{idx}] OK")),
                None => out.push_str(" -> PushBack FALHOU (array ilegível)"),
            }
        }
        if *item_obj != 0 {
            let item_id = ((*item_obj as *const u8).add(0x288) as *const u64).read_unaligned();
            out.push_str(&format!(
                " — item presente (itemID.tdbid={item_id:#018x}) mas RegisterAffectedItem SEM endereço Mac, NÃO registrado (log-only)"
            ));
        }
    }

    out
}

/// axl-fullbody-torso (2026-08-07, cont.41): ACHADO DECISIVO de `enumcomp` — o player tem um
/// `entSkinnedMeshComponent` real com CName='torso' (hash em `+0x40`), mesh resource VÁLIDO em
/// `res_ptr@+0x1f8` (não-null), mas `enabled@+0x8b`==0. Mesmo padrão em `legs`/`shoes` (mesh do
/// corpo TPP, ocultado em FPP — hipótese: é o mecanismo GERAL de ocultação corporal, não algo
/// torso-específico). Esta função reusa a MESMA travessia de `run_enum_skinnedmesh`, acha o
/// componente cujo CName resolve pra `hash_wanted` (comparação de HASH direto via
/// `crate::cname::cname()`, sem round-trip de string), e ESCREVE `1` no offset `+0x8b`
/// (`IComponent::enabled`, já usado com segurança em `IComponent::Toggle` hookado neste projeto
/// desde 2026-07-28 — mesma categoria de risco BAIXA, não a família "Find"/resolve que já
/// crashou). Loga antes/depois pra confirmar a escrita, mas o efeito VISUAL real só é
/// verificável por screenshot — esta função não tira screenshot sozinha.
pub unsafe fn run_toggle_component_by_cname(
    reg: &crate::rtti::Registry,
    player: *mut c_void,
    wanted_name: &str,
) -> String {
    if player.is_null() || !crate::gum::is_readable(player as *const c_void, 0x10) {
        return "[toggle] player nulo/ilegível".to_string();
    }
    let target_cls = reg.class_by_name("entSkinnedMeshComponent");
    if target_cls.is_null() {
        return "[toggle] classe 'entSkinnedMeshComponent' não achada no registry".to_string();
    }
    let hash_wanted = crate::cname::cname(wanted_name);
    let arr = (player as *mut u8).add(0xA0) as *mut c_void;
    if !crate::gum::is_readable(arr as *const c_void, 0x10) {
        return "[toggle] player+0xA0 (ComponentsStorage.components) ilegível".to_string();
    }
    let entries = rd_u64(arr, 0x00) as *const u8;
    let size = core::ptr::read_unaligned((arr as *const u8).add(0x0C) as *const u32);
    if entries.is_null() || size == 0 || size > 4096 {
        return format!("[toggle] array inválido: entries={entries:p} size={size}");
    }
    for i in 0..size as usize {
        let slot = entries.add(i * 16);
        if !crate::gum::is_readable(slot as *const c_void, 16) {
            continue;
        }
        let inst = core::ptr::read_unaligned(slot as *const u64) as *mut c_void;
        if inst.is_null() {
            continue;
        }
        let mut cls = crate::rtti::class_of(inst);
        let mut is_match = false;
        let mut depth = 0usize;
        while !cls.is_null() && depth < 32 {
            if cls == target_cls {
                is_match = true;
                break;
            }
            if !crate::gum::is_readable(cls as *const c_void, 0x18) {
                break;
            }
            cls = rd_u64(cls, 0x10) as *mut c_void;
            depth += 1;
        }
        if !is_match || !crate::gum::is_readable(inst as *const c_void, 0x200) {
            continue;
        }
        let name_hash = (inst as *const u8).add(0x40).cast::<u64>().read_unaligned();
        if name_hash != hash_wanted {
            continue;
        }
        let before = (inst as *const u8).add(0x8b).read_unaligned();
        core::ptr::write_unaligned((inst as *mut u8).add(0x8b), 1u8);
        let after = (inst as *const u8).add(0x8b).read_unaligned();
        let res_ptr = ((inst as *const u8).add(0x1f8) as *const u64).read_unaligned();
        return format!(
            "[toggle] '{wanted_name}' inst={inst:p} enabled ANTES={before} DEPOIS={after} res_ptr={res_ptr:#x}"
        );
    }
    format!("[toggle] '{wanted_name}' (hash={hash_wanted:#x}) NÃO achado entre os componentes do player")
}

/// axl-fullbody-torso (2026-08-07, cont.41, continuação): `toggle` sozinho (escreve `enabled=1`)
/// PERSISTE mas NÃO muda o resultado visual (confirmado por screenshot real, câmera pitch=-60,
/// antes/depois idênticos). Hipótese: o render proxy precisa ser RECONSTRUÍDO pra refletir o novo
/// `enabled` — a mesma função virtual já mapeada e testada como `rebuild-proxy` neste projeto
/// (`vtable+0x288` de `entSkinnedMeshComponent`, `0x100c7eda4`, 144B, observe-only 30/30 amostras
/// sem crash em sessões anteriores). Esta função: acha o componente (mesma travessia), seta
/// `enabled=1`, e CHAMA `0x100c7eda4(inst)` direto (1-arg void, ABI já confirmada) — mesma
/// categoria de risco BAIXA (não-Find/resolve, já observada sem efeito colateral).
pub unsafe fn run_toggle_and_rebuild(
    reg: &crate::rtti::Registry,
    player: *mut c_void,
    wanted_name: &str,
) -> String {
    if player.is_null() || !crate::gum::is_readable(player as *const c_void, 0x10) {
        return "[togglerebuild] player nulo/ilegível".to_string();
    }
    let target_cls = reg.class_by_name("entSkinnedMeshComponent");
    if target_cls.is_null() {
        return "[togglerebuild] classe 'entSkinnedMeshComponent' não achada no registry".to_string();
    }
    let hash_wanted = crate::cname::cname(wanted_name);
    let arr = (player as *mut u8).add(0xA0) as *mut c_void;
    if !crate::gum::is_readable(arr as *const c_void, 0x10) {
        return "[togglerebuild] player+0xA0 ilegível".to_string();
    }
    let entries = rd_u64(arr, 0x00) as *const u8;
    let size = core::ptr::read_unaligned((arr as *const u8).add(0x0C) as *const u32);
    if entries.is_null() || size == 0 || size > 4096 {
        return format!("[togglerebuild] array inválido: entries={entries:p} size={size}");
    }
    for i in 0..size as usize {
        let slot = entries.add(i * 16);
        if !crate::gum::is_readable(slot as *const c_void, 16) {
            continue;
        }
        let inst = core::ptr::read_unaligned(slot as *const u64) as *mut c_void;
        if inst.is_null() {
            continue;
        }
        let mut cls = crate::rtti::class_of(inst);
        let mut is_match = false;
        let mut depth = 0usize;
        while !cls.is_null() && depth < 32 {
            if cls == target_cls {
                is_match = true;
                break;
            }
            if !crate::gum::is_readable(cls as *const c_void, 0x18) {
                break;
            }
            cls = rd_u64(cls, 0x10) as *mut c_void;
            depth += 1;
        }
        if !is_match || !crate::gum::is_readable(inst as *const c_void, 0x200) {
            continue;
        }
        let name_hash = (inst as *const u8).add(0x40).cast::<u64>().read_unaligned();
        if name_hash != hash_wanted {
            continue;
        }
        let before = (inst as *const u8).add(0x8b).read_unaligned();
        core::ptr::write_unaligned((inst as *mut u8).add(0x8b), 1u8);
        let after_write = (inst as *const u8).add(0x8b).read_unaligned();
        let res_before = ((inst as *const u8).add(0x1f8) as *const u64).read_unaligned();
        type OneArgVoidFn = unsafe extern "C" fn(*mut c_void);
        let rebuild: OneArgVoidFn = core::mem::transmute(crate::rebase(0x1_00c7_eda4));
        rebuild(inst);
        let res_after = ((inst as *const u8).add(0x1f8) as *const u64).read_unaligned();
        return format!(
            "[togglerebuild] '{wanted_name}' inst={inst:p} enabled ANTES={before} DEPOIS={after_write} res_ptr ANTES-rebuild={res_before:#x} DEPOIS-rebuild={res_after:#x}"
        );
    }
    format!("[togglerebuild] '{wanted_name}' (hash={hash_wanted:#x}) NÃO achado entre os componentes do player")
}

/// axl-fullbody-torso (2026-08-07, cont.41, continuação): `enabled=1`+rebuild-proxy PERSISTE mas
/// NÃO muda o resultado visual (2 screenshots reais confirmam idêntico). Hipótese nova: o gate
/// real é uma bitmask por-chunk (`chunkMask`, já documentado no projeto pro formato `.xl`/
/// ArchiveXL, nunca localizado em runtime) DENTRO da struct do componente, não `enabled`. Em vez
/// de adivinhar offset, esta função DUMPA os primeiros 0x300 bytes crus do componente achado (pra
/// comparação visual/offline contra um componente sabidamente visível em FPP, ex. o pescoço).
pub unsafe fn run_dump_component_by_cname(
    reg: &crate::rtti::Registry,
    player: *mut c_void,
    wanted_name: &str,
) -> String {
    if player.is_null() || !crate::gum::is_readable(player as *const c_void, 0x10) {
        return "[dumpcomp] player nulo/ilegível".to_string();
    }
    let target_cls = reg.class_by_name("entSkinnedMeshComponent");
    if target_cls.is_null() {
        return "[dumpcomp] classe 'entSkinnedMeshComponent' não achada".to_string();
    }
    let hash_wanted = crate::cname::cname(wanted_name);
    let arr = (player as *mut u8).add(0xA0) as *mut c_void;
    if !crate::gum::is_readable(arr as *const c_void, 0x10) {
        return "[dumpcomp] player+0xA0 ilegível".to_string();
    }
    let entries = rd_u64(arr, 0x00) as *const u8;
    let size = core::ptr::read_unaligned((arr as *const u8).add(0x0C) as *const u32);
    if entries.is_null() || size == 0 || size > 4096 {
        return format!("[dumpcomp] array inválido: entries={entries:p} size={size}");
    }
    for i in 0..size as usize {
        let slot = entries.add(i * 16);
        if !crate::gum::is_readable(slot as *const c_void, 16) {
            continue;
        }
        let inst = core::ptr::read_unaligned(slot as *const u64) as *mut c_void;
        if inst.is_null() {
            continue;
        }
        let mut cls = crate::rtti::class_of(inst);
        let mut is_match = false;
        let mut depth = 0usize;
        while !cls.is_null() && depth < 32 {
            if cls == target_cls {
                is_match = true;
                break;
            }
            if !crate::gum::is_readable(cls as *const c_void, 0x18) {
                break;
            }
            cls = rd_u64(cls, 0x10) as *mut c_void;
            depth += 1;
        }
        if !is_match || !crate::gum::is_readable(inst as *const c_void, 0x300) {
            continue;
        }
        let name_hash = (inst as *const u8).add(0x40).cast::<u64>().read_unaligned();
        if name_hash != hash_wanted {
            continue;
        }
        let mut out = format!("[dumpcomp] '{wanted_name}' inst={inst:p}\n");
        for off in (0x00..0x300usize).step_by(16) {
            let mut line = format!("  +{off:#05x}:");
            for k in 0..16 {
                let b = (inst as *const u8).add(off + k).read_unaligned();
                line.push_str(&format!(" {b:02x}"));
            }
            out.push_str(&line);
            out.push('\n');
        }
        return out;
    }
    format!("[dumpcomp] '{wanted_name}' (hash={hash_wanted:#x}) NÃO achado")
}

// ===== ArchiveXL `#22` (`OverrideStateManager`) — `ApplyChunkMaskOverride` via campo cru =====
//
// Achado do checkpoint 2026-08-12 (`CATALOGO-EXAUSTIVO-ARCHIVEXL.md`, item #22): lendo
// `enablers/ArchiveXL/src/App/Extensions/Garment/Wrapper.cpp` por completo pela 1ª vez,
// `ComponentWrapper::GetChunkMask`/`SetChunkMask`/`GetAppearanceName`/`SetAppearanceName`
// são CAMPO CRU (`aComponent->chunkMask = X; return true;`) — NUNCA `Core::RawFunc`. Isso
// reduz o item de "RE de endereço nativo genérica" pra "offsets de campo confirmados
// contra o header RTTI OFICIAL do jogo real" (gerado da Reflection data pelo próprio
// RED4ext.SDK, não chutado):
//
//   entMeshComponent (RED4ext.SDK/.../Generated/ent/MeshComponent.hpp):
//     mesh: RaRef<CMesh>      @ 0x150   meshAppearance: CName @ 0x190   chunkMask: u64 @ 0x198
//
//   entSkinnedMeshComponent (.../SkinnedMeshComponent.hpp) — MESMOS offsets valem pra
//   entGarmentSkinnedMeshComponent (.../GarmentSkinnedMeshComponent.hpp: extends
//   SkinnedMeshComponent, soma ZERO campo novo antes de 0x2D0 — só padding, confirmado
//   no .hpp):
//     mesh: RaRef<CMesh>      @ 0x228   meshAppearance: CName @ 0x230   chunkMask: u64 @ 0x248
//
//   entMorphTargetSkinnedMeshComponent (.../MorphTargetSkinnedMeshComponent.hpp):
//     morphResource: RaRef<MorphTargetMesh> @ 0x200   meshAppearance: CName @ 0x238
//     chunkMask: u64 @ 0x240
//
// Confiança dos NÚMEROS (não fechamento — regra de ouro do projeto, nenhum destes 3
// campos foi lido/escrito ao vivo neste projeto até agora):
//  - `IComponent::name@0x40` (base comum dos 4 tipos acima) já CONFIRMADO ao vivo nesta
//    MESMA família de classe (`fnv1a64("AttachmentSlots")` exato, probe AttachmentSlots
//    2026-08-12) — é o MESMO offset que `run_toggle_component_by_cname`/
//    `run_dump_component_by_cname` (acima) já leem com sucesso desde 2026-08-07.
//  - `IComponent::isEnabled@0x8b` já em PRODUÇÃO desde 2026-07-28 (`IComponent::Toggle`),
//    usado ao vivo repetidas vezes na mesma investigação de full-body (`toggle`/
//    `togglefull` acima).
//  - `entMeshComponent::mesh@0x150/+0x158` (mesma vizinhança) já usado por
//    `tramp_meshcomponent_get_mesh_resource` (Codeware `#30`, 2026-08-10) — compilou e
//    deployou limpo; o crash daquela tentativa foi na DECLARAÇÃO REDSCRIPT de uma classe
//    `CMesh` nova (categoria de risco DIFERENTE: RTTI bind de ancestralidade), não na
//    leitura do offset em si. `chunkMask`/`meshAppearance` aqui são `uint64_t`/`CName` —
//    tipos primitivos já suportados nativamente pelo redscript, então essa categoria de
//    crash específica (declarar classe nova sem ancestral script-visível) NÃO se aplica.
//  - CORREÇÃO de um candidato fraco anterior: `notes/GARMENT-APPEARANCE-COMPONENT-FACTS.md`
//    §0 testou `torso+0x240` (valor `0xFF..FF`) como candidato a chunkMask do torso
//    (`entGarmentSkinnedMeshComponent`) — pelo header oficial, `+0x240` nessa classe é
//    `visibilityAnimationParam` (um `CName`), NÃO `chunkMask` (que fica em `+0x248`). O
//    valor `0xFF..FF` capturado lá é mais provavelmente essa CName (ou lixo de padding)
//    que o chunkMask de verdade — refinamento de offset, não retestado ao vivo ainda.
//
// `chunkMask`/`meshAppearance` NÃO são refletidos no RTTI redscript (zero hit pra
// "chunkMask" em `redscript-src/` inteiro) — `getf`/`setf` via Reflection não alcançam,
// é offset cru mesmo, sem atalho de reflection.
//
// ⚠️ REGRA DE OURO: nada abaixo foi testado ao vivo. Compila e é logicamente fiel à
// fonte real, mas o item `#22` continua REAL_GAP até um boot confirmar os offsets.

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum GarmentComponentKind {
    /// `entMeshComponent` — folha, ninguém mais `IsA` ele (é IRMÃO de `ISkinTargetComponent`,
    /// não ancestral — por isso vem checado primeiro na mesma ordem do C++ real).
    MeshComponent,
    /// `entSkinnedMeshComponent` OU `entGarmentSkinnedMeshComponent` — offsets IDÊNTICOS
    /// (Garment não soma campo antes de 0x2D0), então tratados como 1 kind só.
    SkinnedFamily,
    /// `entMorphTargetSkinnedMeshComponent`.
    MorphTarget,
    /// Nenhum dos 4 tipos suportados — `ComponentWrapper::IsMeshComponent()` seria `false`.
    Unsupported,
}

/// Walk do parent chain (`CClass+0x10`) — MESMO idioma já usado em
/// `run_toggle_component_by_cname`/`run_dump_component_by_cname` acima, copiado aqui
/// isolado de propósito (evita tocar código já provado ao vivo nessas 2 funções).
unsafe fn class_is_a(mut cls: *mut c_void, target: *mut c_void) -> bool {
    if target.is_null() {
        return false;
    }
    let mut depth = 0usize;
    while !cls.is_null() && depth < 32 {
        if cls == target {
            return true;
        }
        if !crate::gum::is_readable(cls as *const c_void, 0x18) {
            return false;
        }
        cls = rd_u64(cls, 0x10) as *mut c_void;
        depth += 1;
    }
    false
}

/// Classifica um componente na MESMA ordem de `App::ComponentWrapper::ComponentWrapper`
/// (Wrapper.cpp:83-106): `MeshComponent` primeiro, depois `MorphTargetSkinnedMeshComponent`,
/// depois `GarmentSkinnedMeshComponent` (tem que vir ANTES de `SkinnedMeshComponent` puro —
/// Garment `IsA` Skinned também, checar na ordem errada classificaria Garment como Skinned
/// genérico, o que na prática não muda offset mas quebraria a fidelidade à fonte), por
/// último `SkinnedMeshComponent`.
unsafe fn detect_garment_component_kind(reg: &crate::rtti::Registry, inst: *mut c_void) -> GarmentComponentKind {
    if inst.is_null() {
        return GarmentComponentKind::Unsupported;
    }
    let cls = crate::rtti::class_of(inst);
    if cls.is_null() {
        return GarmentComponentKind::Unsupported;
    }
    if class_is_a(cls, reg.class_by_name("entMeshComponent")) {
        return GarmentComponentKind::MeshComponent;
    }
    if class_is_a(cls, reg.class_by_name("entMorphTargetSkinnedMeshComponent")) {
        return GarmentComponentKind::MorphTarget;
    }
    if class_is_a(cls, reg.class_by_name("entGarmentSkinnedMeshComponent")) {
        return GarmentComponentKind::SkinnedFamily;
    }
    if class_is_a(cls, reg.class_by_name("entSkinnedMeshComponent")) {
        return GarmentComponentKind::SkinnedFamily;
    }
    GarmentComponentKind::Unsupported
}

/// Offset de `chunkMask` (`uint64_t`) por kind — confirmado contra o header RTTI oficial
/// (ver comentário grande acima). `None` = `Unsupported` (mesmo veredito de
/// `ComponentWrapper::IsMeshComponent()==false`).
fn garment_chunk_mask_offset(kind: GarmentComponentKind) -> Option<usize> {
    match kind {
        GarmentComponentKind::MeshComponent => Some(0x198),
        GarmentComponentKind::SkinnedFamily => Some(0x248),
        GarmentComponentKind::MorphTarget => Some(0x240),
        GarmentComponentKind::Unsupported => None,
    }
}

/// Offset de `meshAppearance` (`CName`) por kind — bônus, mesma fonte/confiança do de
/// cima. Fica pronto pra uma futura `ApplyAppearanceOverride`, mas NÃO wired a nenhum
/// comando de console ainda (fora do escopo mínimo desta rodada: "no mínimo
/// ApplyChunkMaskOverride").
fn garment_mesh_appearance_offset(kind: GarmentComponentKind) -> Option<usize> {
    match kind {
        GarmentComponentKind::MeshComponent => Some(0x190),
        GarmentComponentKind::SkinnedFamily => Some(0x230),
        GarmentComponentKind::MorphTarget => Some(0x238),
        GarmentComponentKind::Unsupported => None,
    }
}

/// Offset do campo `RaRef<CMesh> mesh` (`MeshComponent`/`SkinnedFamily`) ou
/// `RaRef<MorphTargetMesh> morphResource` (`MorphTarget`) — item ArchiveXL `#22`/Codeware
/// `#168`, `ComponentWrapper::GetResourcePath`/`SetResourcePath` (`Wrapper.cpp:149-183`).
/// **`RaRef<T>` (`Red::ResourceAsyncReference<T>`) é só um `ResourcePath path@0x00`, 8 bytes**
/// (`RED4ext.SDK/include/RED4ext/ResourceReference.hpp`, `RED4EXT_ASSERT_SIZE(
/// ResourceAsyncReference<>, 0x8)`/`RED4EXT_ASSERT_OFFSET(...,path,0x0)`, confirmado no header
/// oficial vendorizado) — `SetComponentResourcePath` (`aComponent->mesh = aPath;`) e o campo
/// `mesh`/`morphResource` em si são a MESMA leitura/escrita de 8 bytes, sem indireção. Mesma
/// confiança do `garment_chunk_mask_offset`/`garment_mesh_appearance_offset` (offsets
/// cross-validados contra os headers RTTI oficiais `Generated/ent/*.hpp` — `mesh@0x150`
/// `MeshComponent`, `mesh@0x228` `SkinnedFamily`/`GarmentSkinnedMeshComponent` (mesmos offsets,
/// Garment não soma campo antes de 0x2D0), `morphResource@0x200` `MorphTargetSkinnedMesh
/// Component`), nunca testado ao vivo até esta rodada.
fn garment_mesh_path_offset(kind: GarmentComponentKind) -> Option<usize> {
    match kind {
        GarmentComponentKind::MeshComponent => Some(0x150),
        GarmentComponentKind::SkinnedFamily => Some(0x228),
        GarmentComponentKind::MorphTarget => Some(0x200),
        GarmentComponentKind::Unsupported => None,
    }
}

/// `ComponentWrapper::GetResourcePath` (`Wrapper.cpp:149-165`) — campo cru de 8 bytes (o
/// `RaRef<T>` inteiro É o `ResourcePath`, ver `garment_mesh_path_offset`).
unsafe fn component_get_resource_path(inst: *mut c_void, kind: GarmentComponentKind) -> Option<u64> {
    let off = garment_mesh_path_offset(kind)?;
    if !crate::gum::is_readable((inst as *const u8).add(off) as *const c_void, 8) {
        return None;
    }
    Some(rd_u64(inst, off))
}

/// `ComponentWrapper::SetResourcePath` (`Wrapper.cpp:167-183`) — `aComponent->mesh = aPath;
/// return true;` (ou `morphResource` pro kind `MorphTarget`). Campo cru, fiel à fonte real.
unsafe fn component_set_resource_path(inst: *mut c_void, kind: GarmentComponentKind, value: u64) -> bool {
    let off = match garment_mesh_path_offset(kind) {
        Some(o) => o,
        None => return false,
    };
    if !crate::gum::is_readable((inst as *const u8).add(off) as *const c_void, 8) {
        return false;
    }
    wr_u64(inst, off, value);
    true
}

/// `ComponentWrapper::GetChunkMask` (Wrapper.cpp:350-366) — campo cru, sem native nenhuma.
unsafe fn component_get_chunk_mask(inst: *mut c_void, kind: GarmentComponentKind) -> Option<u64> {
    let off = garment_chunk_mask_offset(kind)?;
    if !crate::gum::is_readable((inst as *const u8).add(off) as *const c_void, 8) {
        return None;
    }
    Some(rd_u64(inst, off))
}

