/// Enumera TODOS os componentes da entidade (`Entity+0xA0`, mesmo walk já provado em
/// `find_garment_component_by_cname`/`run_enum_skinnedmesh` — aqui SEM pré-filtrar por
/// classe, já que a tabela de tags cobre `MeshComponent`/`SkinnedFamily`/`MorphTarget`
/// juntos), compara `IComponent::name@0x40` (CName, EXATO) contra as chaves da tabela da tag
/// e aplica `component_set_chunk_mask` onde bate. `dry_run=true` conta o que SERIA aplicado
/// sem escrever nada (mesma disciplina observe-only-primeiro do resto do projeto). Devolve
/// `(componentes_verificados, nomes_batendo, aplicados_com_sucesso)`.
unsafe fn apply_visual_tag_override(
    reg: &crate::rtti::Registry,
    entity: *mut c_void,
    tag: &str,
    dry_run: bool,
) -> (usize, usize, usize) {
    let table = match builtin_tag_overrides_runtime(tag) {
        Some(t) => t,
        None => return (0, 0, 0),
    };
    if entity.is_null() || !crate::gum::is_readable(entity as *const c_void, 0x10) {
        return (0, 0, 0);
    }
    let arr = (entity as *mut u8).add(0xA0) as *mut c_void;
    if !crate::gum::is_readable(arr as *const c_void, 0x10) {
        return (0, 0, 0);
    }
    let entries = rd_u64(arr, 0x00) as *const u8;
    let size = core::ptr::read_unaligned((arr as *const u8).add(0x0C) as *const u32);
    if entries.is_null() || size == 0 || size > 4096 {
        return (0, 0, 0);
    }
    // Pré-computa o hash de cada chave da tabela 1x (mesmo `crate::cname::cname` já usado por
    // `find_garment_component_by_cname` — a MESMA função de interning/hash, não uma cópia).
    let wanted: Vec<(u64, u64)> =
        table.iter().map(|(name, (_showing, mask))| (crate::cname::cname(name), *mask)).collect();
    let mut checked = 0usize;
    let mut matched = 0usize;
    let mut applied = 0usize;
    for i in 0..size as usize {
        let slot = entries.add(i * 16);
        if !crate::gum::is_readable(slot as *const c_void, 16) {
            continue;
        }
        let inst = core::ptr::read_unaligned(slot as *const u64) as *mut c_void;
        if inst.is_null() || !crate::gum::is_readable(inst as *const c_void, 0x60) {
            continue;
        }
        checked += 1;
        let name_hash = (inst as *const u8).add(0x40).cast::<u64>().read_unaligned();
        if let Some(&(_, mask)) = wanted.iter().find(|(h, _)| *h == name_hash) {
            matched += 1;
            let kind = detect_garment_component_kind(reg, inst);
            if kind == GarmentComponentKind::Unsupported {
                continue;
            }
            if dry_run {
                applied += 1;
            } else if component_set_chunk_mask(inst, kind, mask) {
                applied += 1;
            }
        }
    }
    (checked, matched, applied)
}

// ===== ArchiveXL `#22` (`App::ComponentState`/`EntityState`, combinação MULTI-MOD por hash) —
// round 6, 2026-08-12. Porte do algoritmo já fechado OFFLINE em `bwms-core::xl.rs` desde
// 2026-08-11 (`ComponentState::AddHidingChunkMaskOverride`/`AddShowingChunkMaskOverride`/
// `RemoveChunkMaskOverride`/`GetOverriddenChunkMask`) pro dylib RUNTIME — a peça que a nota de
// `apply_visual_tag_override` (round 2, acima) já documentava como faltando: "a combinação
// MULTI-MOD por hash... NÃO portada... 2 mods na mesma tag/componente... o último a chamar
// vence". `bwms-core` nunca foi dependência de `cp77-console` (mesmo achado de fronteira de
// crate já corrigido hoje pra `#21`/`#23`/`#48`) — a struct pura é REIMPLEMENTADA aqui (não
// importada), mesmo algoritmo (`Garment/States.cpp`, RE 2026-08-11), testável offline.
//
// Algoritmo fiel: hiding = AND cumulativo por `mod_hash` (inicia em `!0`, "sem restrição"),
// showing = OR cumulativo por `mod_hash` (inicia em `0`, "nada forçado"), resultado final =
// `baseline & hiding_combinado | showing_combinado`. `mod_hash` é calculado pelo CALLER (ex.
// hash do nome do mod) — cada hash distinto = 1 fonte/1 mod, igual à fonte real.
//
// Divergência de escopo CONSCIENTE, documentada: `baseline` (o "originalMask" que
// `GetOverriddenChunkMask` combina) é CACHEADO na 1ª vez que QUALQUER mod aplica um override
// neste par (entidade,componente) — lido via `component_get_chunk_mask` ANTES de qualquer
// escrita nossa. A fonte C++ real não documenta de onde `originalMask` vem em todo call-site
// (provavelmente um valor cacheado alhures no pipeline de garment, nunca portado) — cachear no
// 1º touch é o único jeito seguro de recompor overrides sem reler um campo que a gente mesma
// já sobrescreveu.
//
// ⚠️ REGRA DE OURO: nada abaixo foi testado ao vivo. Item `#22` continua REAL_GAP.

/// Estado de override multi-mod por (entidade,componente) — porte de `App::ComponentState`.
#[derive(Debug, Clone)]
struct TagOverrideState {
    baseline: u64,
    hiding: Vec<(u64, u64)>,
    showing: Vec<(u64, u64)>,
}

impl TagOverrideState {
    fn new(baseline: u64) -> Self {
        Self { baseline, hiding: Vec::new(), showing: Vec::new() }
    }

    /// `ComponentState::AddHidingChunkMaskOverride(hash, mask)` — AND cumulativo por hash.
    fn add_hiding(&mut self, mod_hash: u64, mask: u64) {
        if let Some(e) = self.hiding.iter_mut().find(|(h, _)| *h == mod_hash) {
            e.1 &= mask;
        } else {
            self.hiding.push((mod_hash, mask));
        }
    }

    /// `ComponentState::AddShowingChunkMaskOverride(hash, mask)` — OR cumulativo por hash.
    fn add_showing(&mut self, mod_hash: u64, mask: u64) {
        if let Some(e) = self.showing.iter_mut().find(|(h, _)| *h == mod_hash) {
            e.1 |= mask;
        } else {
            self.showing.push((mod_hash, mask));
        }
    }

    /// `ComponentState::RemoveChunkMaskOverride(hash)` — remove hiding E showing daquele hash
    /// (1 fonte/1 mod, o gatilho real de "mod desinstalado"). Devolve `true` se havia algo.
    fn remove(&mut self, mod_hash: u64) -> bool {
        let had = self.hiding.iter().any(|(h, _)| *h == mod_hash) || self.showing.iter().any(|(h, _)| *h == mod_hash);
        self.hiding.retain(|(h, _)| *h != mod_hash);
        self.showing.retain(|(h, _)| *h != mod_hash);
        had
    }

    /// `ComponentState::GetOverriddenChunkMask(originalMask)` — combina TODOS os hashes.
    fn combined(&self) -> u64 {
        let mut mask = self.baseline;
        for (_, h) in &self.hiding {
            mask &= h;
        }
        for (_, s) in &self.showing {
            mask |= s;
        }
        mask
    }

    fn is_empty(&self) -> bool {
        self.hiding.is_empty() && self.showing.is_empty()
    }
}

/// Chave = `(entity_ptr as u64, component_name_hash)` — mesma composição de chave-dupla já
/// usada noutros registries deste arquivo (ex. `ENTITYTARGET_DEFINITION_STATES`). `Vec` linear
/// (poucos componentes com override ativo por vez, mesma disciplina de escala do resto do
/// arquivo — não é um hot-path por-frame).
static TAG_OVERRIDE_STATE: Mutex<Vec<((u64, u64), TagOverrideState)>> = Mutex::new(Vec::new());

/// Aplica `tag` no(s) componente(s) que baterem, registrando a contribuição sob `mod_hash`
/// (AND-cumulativo pra entradas "hide", OR-cumulativo pra entradas "show" — fiel ao algoritmo
/// `ComponentState` real). Múltiplos mods aplicando a MESMA tag no MESMO componente agora
/// COMBINAM (em vez de "o último a chamar vence", o comportamento antigo de
/// `apply_visual_tag_override`, que continua existindo pra uso single-mod/round 2). `dry_run`
/// só conta (zero mutação, zero registro em `TAG_OVERRIDE_STATE`). Devolve `(componentes_
/// verificados, nomes_batendo, aplicados_com_sucesso)`.
/// Composição do achado "Cross-ref Codeware `#28`/`#247`" já documentado no checkpoint do
/// item `#22` (round 5 do dia): o slot de vtable `RefreshAppearance` (`entSkinnedMeshComponent`
/// vtable `+0x288` Itanium, `0x100c7eda4`) já foi confirmado+testado AO VIVO 2x, zero crash
/// (`run_toggle_and_rebuild`/comando `togglerebuild`, 2026-08-07) — mas nunca tinha sido
/// composto com a ESCRITA de `chunkMask` (só com o campo `enabled`). Fecha o gap entre "campo
/// escrito" e "efeito visual", exatamente o "efeito visual pendente" que a nota do `#21`/`#97`
/// (`EnableGarmentOffsets`) já documentava como faltando. Zero endereço nativo NOVO — mesma
/// função já em produção, só chamada de um lugar novo. Restrito a `SkinnedFamily`
/// (`entSkinnedMeshComponent`/`entGarmentSkinnedMeshComponent`, MESMO vtable — confirmado no
/// header oficial, "Garment soma zero campo novo antes de 0x2D0") — o offset NUNCA foi
/// confirmado independentemente pra `MeshComponent`/`MorphTarget`, então esses 2 kinds ficam
/// de fora de propósito (não chamar endereço não-confirmado pra classe diferente).
unsafe fn refresh_skinned_appearance(inst: *mut c_void, kind: GarmentComponentKind) -> bool {
    if kind != GarmentComponentKind::SkinnedFamily {
        return false;
    }
    if !crate::gum::is_readable(inst as *const c_void, 0x10) {
        return false;
    }
    type OneArgVoidFn = unsafe extern "C" fn(*mut c_void);
    let target = crate::rebase(0x1_00c7_eda4);
    if target.is_null() {
        return false;
    }
    let rebuild: OneArgVoidFn = core::mem::transmute(target);
    rebuild(inst);
    true
}

unsafe fn apply_visual_tag_override_for_mod(
    reg: &crate::rtti::Registry,
    entity: *mut c_void,
    tag: &str,
    mod_hash: u64,
    dry_run: bool,
    refresh: bool,
) -> (usize, usize, usize) {
    let table = match builtin_tag_overrides_runtime(tag) {
        Some(t) => t,
        None => return (0, 0, 0),
    };
    if entity.is_null() || !crate::gum::is_readable(entity as *const c_void, 0x10) {
        return (0, 0, 0);
    }
    let arr = (entity as *mut u8).add(0xA0) as *mut c_void;
    if !crate::gum::is_readable(arr as *const c_void, 0x10) {
        return (0, 0, 0);
    }
    let entries = rd_u64(arr, 0x00) as *const u8;
    let size = core::ptr::read_unaligned((arr as *const u8).add(0x0C) as *const u32);
    if entries.is_null() || size == 0 || size > 4096 {
        return (0, 0, 0);
    }
    let wanted: Vec<(u64, bool, u64)> =
        table.iter().map(|(name, (showing, mask))| (crate::cname::cname(name), *showing, *mask)).collect();
    let entity_key = entity as u64;
    let mut checked = 0usize;
    let mut matched = 0usize;
    let mut applied = 0usize;
    for i in 0..size as usize {
        let slot = entries.add(i * 16);
        if !crate::gum::is_readable(slot as *const c_void, 16) {
            continue;
        }
        let inst = core::ptr::read_unaligned(slot as *const u64) as *mut c_void;
        if inst.is_null() || !crate::gum::is_readable(inst as *const c_void, 0x60) {
            continue;
        }
        checked += 1;
        let name_hash = (inst as *const u8).add(0x40).cast::<u64>().read_unaligned();
        let Some(&(_, showing, mask)) = wanted.iter().find(|(h, _, _)| *h == name_hash) else {
            continue;
        };
        matched += 1;
        let kind = detect_garment_component_kind(reg, inst);
        if kind == GarmentComponentKind::Unsupported {
            continue;
        }
        if dry_run {
            applied += 1;
            continue;
        }
        let comp_key = (entity_key, name_hash);
        let combined = match TAG_OVERRIDE_STATE.lock() {
            Ok(mut guard) => {
                let idx = match guard.iter().position(|(k, _)| *k == comp_key) {
                    Some(i) => i,
                    None => {
                        let baseline = component_get_chunk_mask(inst, kind).unwrap_or(!0u64);
                        guard.push((comp_key, TagOverrideState::new(baseline)));
                        guard.len() - 1
                    }
                };
                let st = &mut guard[idx].1;
                if showing {
                    st.add_showing(mod_hash, mask);
                } else {
                    st.add_hiding(mod_hash, mask);
                }
                st.combined()
            }
            Err(_) => continue,
        };
        if component_set_chunk_mask(inst, kind, combined) {
            applied += 1;
            if refresh {
                refresh_skinned_appearance(inst, kind);
            }
        }
    }
    (checked, matched, applied)
}

/// Remove a contribuição de `mod_hash` (ex. um mod sendo desinstalado — `removal-safety`, a
/// regra-mãe do projeto: nada deve deixar rastro permanente que sobrevive à desinstalação) da
/// tag `tag` em cada componente da entidade que já tinha estado registrado — recompõe o mask
/// combinando o que sobra dos OUTROS mods + o baseline cacheado, e escreve de volta.
/// Componentes cujo estado fica VAZIO depois são removidos do registry (não vazam pra sempre —
/// o baseline original é restaurado byte-a-byte). Devolve `(componentes_com_estado,
/// removidos_de_verdade, reescritos_com_sucesso)`.
unsafe fn remove_visual_tag_override_for_mod(
    reg: &crate::rtti::Registry,
    entity: *mut c_void,
    tag: &str,
    mod_hash: u64,
    refresh: bool,
) -> (usize, usize, usize) {
    let table = match builtin_tag_overrides_runtime(tag) {
        Some(t) => t,
        None => return (0, 0, 0),
    };
    if entity.is_null() || !crate::gum::is_readable(entity as *const c_void, 0x10) {
        return (0, 0, 0);
    }
    let entity_key = entity as u64;
    let wanted_names: Vec<u64> = table.iter().map(|(name, _)| crate::cname::cname(name)).collect();
    let arr = (entity as *mut u8).add(0xA0) as *mut c_void;
    if !crate::gum::is_readable(arr as *const c_void, 0x10) {
        return (0, 0, 0);
    }
    let entries = rd_u64(arr, 0x00) as *const u8;
    let size = core::ptr::read_unaligned((arr as *const u8).add(0x0C) as *const u32);
    if entries.is_null() || size == 0 || size > 4096 {
        return (0, 0, 0);
    }
    let mut with_state = 0usize;
    let mut removed = 0usize;
    let mut rewritten = 0usize;
    for i in 0..size as usize {
        let slot = entries.add(i * 16);
        if !crate::gum::is_readable(slot as *const c_void, 16) {
            continue;
        }
        let inst = core::ptr::read_unaligned(slot as *const u64) as *mut c_void;
        if inst.is_null() || !crate::gum::is_readable(inst as *const c_void, 0x60) {
            continue;
        }
        let name_hash = (inst as *const u8).add(0x40).cast::<u64>().read_unaligned();
        if !wanted_names.contains(&name_hash) {
            continue;
        }
        let comp_key = (entity_key, name_hash);
        // `(havia_estado, teve_algo_removido, valor_pra_reescrever_ou_none)`.
        let outcome: (bool, bool, Option<u64>) = match TAG_OVERRIDE_STATE.lock() {
            Ok(mut guard) => match guard.iter().position(|(k, _)| *k == comp_key) {
                None => (false, false, None),
                Some(idx) => {
                    let had = guard[idx].1.remove(mod_hash);
                    if !had {
                        (true, false, None)
                    } else if guard[idx].1.is_empty() {
                        let baseline = guard[idx].1.baseline;
                        guard.remove(idx);
                        (true, true, Some(baseline))
                    } else {
                        (true, true, Some(guard[idx].1.combined()))
                    }
                }
            },
            Err(_) => (false, false, None),
        };
        if outcome.0 {
            with_state += 1;
        }
        if !outcome.1 {
            continue;
        }
        removed += 1;
        if let Some(v) = outcome.2 {
            let kind = detect_garment_component_kind(reg, inst);
            if kind != GarmentComponentKind::Unsupported && component_set_chunk_mask(inst, kind, v) {
                rewritten += 1;
                if refresh {
                    refresh_skinned_appearance(inst, kind);
                }
            }
        }
    }
    (with_state, removed, rewritten)
}

/// `vtagapplymod <tag> <modHash>` — variante MULTI-MOD de `vtagapply`: registra a contribuição
/// sob `mod_hash` em vez de sobrescrever sem rastro. Segundo mod aplicando a MESMA tag no MESMO
/// componente COMBINA (AND-hiding/OR-showing) em vez de vencer sozinho.
pub unsafe fn run_visual_tag_override_apply_for_mod(
    reg: &crate::rtti::Registry,
    player: *mut c_void,
    tag: &str,
    mod_hash: u64,
) -> String {
    let (checked, matched, applied) = apply_visual_tag_override_for_mod(reg, player, tag, mod_hash, false, false);
    format!(
        "[vtagapplymod] tag='{tag}' mod_hash={mod_hash:#018x} componentes_verificados={checked} nomes_batendo={matched} aplicados={applied}"
    )
}

/// `vtagremovemod <tag> <modHash>` — desfaz a contribuição de `mod_hash` (uninstall-safety).
pub unsafe fn run_visual_tag_override_remove_for_mod(
    reg: &crate::rtti::Registry,
    player: *mut c_void,
    tag: &str,
    mod_hash: u64,
) -> String {
    let (with_state, removed, rewritten) = remove_visual_tag_override_for_mod(reg, player, tag, mod_hash, false);
    format!(
        "[vtagremovemod] tag='{tag}' mod_hash={mod_hash:#018x} componentes_com_estado={with_state} removidos={removed} reescritos={rewritten}"
    )
}

/// `vtagapplymodrefresh <tag> <modHash>` — igual a `vtagapplymod`, mas TAMBÉM chama
/// `refresh_skinned_appearance` (o `RefreshAppearance` já provado ao vivo 2x via
/// `togglerebuild`) em cada componente `SkinnedFamily` escrito com sucesso — fecha o gap entre
/// "campo `chunkMask` escrito" e "efeito VISUAL de verdade", que ficava pendente desde a nota
/// original do item `#21`/`#97` ("plumbing correto, efeito visual pendente"). Variante SEPARADA
/// de propósito — `vtagapplymod`/`ApplyVisualTagOverrideForMod` continuam sem chamar isso, pra
/// não misturar 2 categorias de risco (escrita de campo puro vs. dispatch de função nativa) na
/// MESMA prova ao vivo já pendente.
pub unsafe fn run_visual_tag_override_apply_for_mod_refresh(
    reg: &crate::rtti::Registry,
    player: *mut c_void,
    tag: &str,
    mod_hash: u64,
) -> String {
    let (checked, matched, applied) = apply_visual_tag_override_for_mod(reg, player, tag, mod_hash, false, true);
    format!(
        "[vtagapplymodrefresh] tag='{tag}' mod_hash={mod_hash:#018x} componentes_verificados={checked} nomes_batendo={matched} aplicados={applied} (refresh chamado nos SkinnedFamily aplicados)"
    )
}

/// `vtagremovemodrefresh <tag> <modHash>` — contraparte de remoção COM refresh.
pub unsafe fn run_visual_tag_override_remove_for_mod_refresh(
    reg: &crate::rtti::Registry,
    player: *mut c_void,
    tag: &str,
    mod_hash: u64,
) -> String {
    let (with_state, removed, rewritten) = remove_visual_tag_override_for_mod(reg, player, tag, mod_hash, true);
    format!(
        "[vtagremovemodrefresh] tag='{tag}' mod_hash={mod_hash:#018x} componentes_com_estado={with_state} removidos={removed} reescritos={rewritten} (refresh chamado nos SkinnedFamily reescritos)"
    )
}

#[cfg(test)]
mod archivexl_multimod_tests {
    use super::TagOverrideState;

    // Testes 100% offline da lógica PURA de combinação (`TagOverrideState`) — a parte que
    // caminha memória viva (`apply_visual_tag_override_for_mod`) não é testável fora do
    // processo do jogo, mesma disciplina já usada em `component_get_chunk_mask`/`set` (só a
    // tabela/algoritmo puro ganha teste offline).

    #[test]
    fn dois_mods_hiding_combinam_por_and() {
        // Mod A esconde chunks 0-3 (mask=!0b1111), Mod B esconde chunks 4-7 (mask=!0b11110000).
        // Combinado: nem A nem B sozinho esconderia tudo, mas AND dos dois esconde os 8 juntos.
        let mut st = TagOverrideState::new(!0u64); // baseline = tudo visível
        st.add_hiding(0xAAAA, !0b1111u64);
        st.add_hiding(0xBBBB, !0b1111_0000u64);
        assert_eq!(st.combined(), !0b1111_1111u64);
    }

    #[test]
    fn dois_mods_showing_combinam_por_or() {
        // Mod A força bit 0 visível, Mod B força bit 1 visível — combinado força os 2.
        let mut st = TagOverrideState::new(0u64); // baseline = tudo escondido
        st.add_showing(0xAAAA, 0b001u64);
        st.add_showing(0xBBBB, 0b010u64);
        assert_eq!(st.combined(), 0b011u64);
    }

    #[test]
    fn remove_de_1_mod_preserva_o_outro() {
        // Cenário do achado de escopo do round 2: "2 mods na mesma tag/componente" — agora
        // desinstalar 1 deixa o outro intacto (removal-safety).
        let mut st = TagOverrideState::new(!0u64);
        st.add_hiding(0xAAAA, !0b1111u64);
        st.add_hiding(0xBBBB, !0b1111_0000u64);
        assert!(st.remove(0xAAAA));
        assert_eq!(st.combined(), !0b1111_0000u64); // só o hiding de B sobrevive
        assert!(!st.is_empty());
    }

    #[test]
    fn remove_do_ultimo_mod_esvazia_o_estado() {
        let mut st = TagOverrideState::new(0x1234u64);
        st.add_showing(0xAAAA, 0b1u64);
        assert!(st.remove(0xAAAA));
        assert!(st.is_empty());
        assert_eq!(st.combined(), 0x1234u64); // volta pro baseline puro
    }

    #[test]
    fn remove_de_hash_nunca_registrado_devolve_false() {
        let mut st = TagOverrideState::new(!0u64);
        st.add_hiding(0xAAAA, !0b1111u64);
        assert!(!st.remove(0xDEAD));
        assert!(!st.is_empty()); // nada mudou
    }

    #[test]
    fn mesmo_mod_reaplicando_a_mesma_tag_e_idempotente() {
        // Chamar add_hiding 2x com o MESMO hash+mask não deveria "acumular" além do AND normal
        // (AND de X com X é X) — confirma que reaplicar não corrompe o estado.
        let mut st = TagOverrideState::new(!0u64);
        st.add_hiding(0xAAAA, !0b1111u64);
        st.add_hiding(0xAAAA, !0b1111u64);
        assert_eq!(st.combined(), !0b1111u64);
    }
}

/// `vtagcount <tag>` — variante DRY-RUN de `apply_visual_tag_override` contra o PLAYER
/// (observe-only, zero mutação). 1º passo seguro antes de `vtagapply`.
pub unsafe fn run_visual_tag_override_count(reg: &crate::rtti::Registry, player: *mut c_void, tag: &str) -> String {
    let (checked, matched, _) = apply_visual_tag_override(reg, player, tag, true);
    format!("[vtagcount] tag='{tag}' componentes_verificados={checked} nomes_batendo={matched} (dry-run, zero mutação)")
}

/// `vtagapply <tag>` — ESCRITA REAL. Aplica a `ChunkMask` de cada componente cujo nome bate
/// (exato) com a tabela built-in da tag, direto no `chunkMask` do componente vivo do PLAYER.
pub unsafe fn run_visual_tag_override_apply(reg: &crate::rtti::Registry, player: *mut c_void, tag: &str) -> String {
    let (checked, matched, applied) = apply_visual_tag_override(reg, player, tag, false);
    format!("[vtagapply] tag='{tag}' componentes_verificados={checked} nomes_batendo={matched} aplicados={applied}")
}

#[cfg(test)]
mod archivexl_tag_override_tests {
    use super::{builtin_tag_overrides_runtime, garment_tag_chunk_mask};

    // Vetores golden IDÊNTICOS aos já testados em `bwms-core/src/xl.rs` (mesma fonte C++,
    // `Tags.cpp`) — confirma que a duplicação pro dylib runtime não divergiu da versão já
    // provada offline (mesmo espírito de `archivexl_dynamic_appearance_tests` acima).

    #[test]
    fn hide_torso_bate_com_a_fonte_real() {
        let overrides = builtin_tag_overrides_runtime("hide_Torso").unwrap();
        assert_eq!(overrides.len(), 8);
        let (_, (showing, mask)) = overrides.iter().find(|(n, _)| *n == "t0_000_pma_base__full").unwrap();
        assert_eq!(*mask, !0b1111u64); // hide([0,1,2,3])
        assert!(!showing); // #22 round 6: entrada "hide" precisa ficar marcada AND, não OR
        let (_, (_, mask_n0)) = overrides.iter().find(|(n, _)| *n == "n0_").unwrap();
        assert_eq!(*mask_n0, 0); // Hide() sem chunks = mask 0 (nunca invertido, regra do from_chunks)
    }

    #[test]
    fn highheels_tem_show_positivo_e_hide_negativo() {
        let overrides = builtin_tag_overrides_runtime("HighHeels").unwrap();
        let (_, (showing, mask)) = overrides.iter().find(|(n, _)| *n == "l0_000_pma_base__high_heels").unwrap();
        assert_eq!(*mask, 0b111); // show([0,1,2]), SEM inversão
        assert!(showing); // #22 round 6: entrada "show" precisa ficar marcada OR, não AND
        let (_, (showing_full, mask_full)) = overrides.iter().find(|(n, _)| *n == "t0_000_pma_base__full").unwrap();
        assert_eq!(*mask_full, !0b1110_0000u64); // hide([5,6,7])
        assert!(!showing_full);
    }

    #[test]
    fn flatshoes_espelha_highheels_com_slot_diferente() {
        let overrides = builtin_tag_overrides_runtime("FlatShoes").unwrap();
        assert_eq!(overrides.len(), 5);
        let (_, (showing, mask)) = overrides.iter().find(|(n, _)| *n == "l0_000_pwa_base__flat_shoes").unwrap();
        assert_eq!(*mask, 0b111);
        assert!(showing);
    }

    #[test]
    fn hide_head_12_partes_todas_hide_all() {
        let overrides = builtin_tag_overrides_runtime("hide_Head").unwrap();
        assert_eq!(overrides.len(), 12);
        assert!(overrides.iter().all(|(_, (showing, m))| *m == 0 && !showing));
    }

    #[test]
    fn nome_desconhecido_devolve_none() {
        assert!(builtin_tag_overrides_runtime("tag_que_nao_existe").is_none());
    }

    #[test]
    fn todas_as_14_tags_reais_resolvem() {
        let tags = [
            "hide_Head",
            "hide_Arms",
            "hide_Torso",
            "hide_LowerAbdomen",
            "hide_UpperAbdomen",
            "hide_CollarBone",
            "hide_Chest",
            "hide_Legs",
            "hide_Thighs",
            "hide_Calves",
            "hide_Ankles",
            "hide_Feet",
            "HighHeels",
            "FlatShoes",
        ];
        for t in tags {
            assert!(builtin_tag_overrides_runtime(t).is_some(), "tag '{t}' deveria resolver");
        }
    }

    #[test]
    fn chunk_mask_helper_bate_com_o_algoritmo_documentado_no_item_18() {
        // ChunkMask::Set: show=OR direto; hide=complemento (só se mask!=0).
        assert_eq!(garment_tag_chunk_mask(false, &[5, 6, 7]), !0b1110_0000u64);
        assert_eq!(garment_tag_chunk_mask(true, &[0, 1, 2]), 0b111);
        assert_eq!(garment_tag_chunk_mask(false, &[]), 0);
    }
}

/// `ArchiveXL.GetVisualTagOverrideCount(entity: wref<Entity>, tag: String) -> Int32` — dry-run
/// redscript-facing de `apply_visual_tag_override` (zero mutação). Devolve a contagem de
/// componentes cujo nome bateu com a tabela da tag (não necessariamente aplicável — kind
/// `Unsupported` conta como "batendo" mas não seria escrito por `ApplyVisualTagOverride`).
unsafe extern "C" fn tramp_archivexl_get_visual_tag_override_count(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let func = current_native_func();
    let (args, strings) = rtti::read_params_consuming_with_strings(func, frame);
    let entity = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let tag = strings.get(1).cloned().flatten().unwrap_or_default();
    let (checked, matched, _applied) = match crate::registry() {
        Some(reg) if rtti::sane(entity) => apply_visual_tag_override(reg, entity, &tag, true),
        _ => (0, 0, 0),
    };
    crate::log(&format!(
        "[reg] >>> ArchiveXL.GetVisualTagOverrideCount(entity={entity:p}, tag='{tag}') -> checked={checked} matched={matched}"
    ));
    write_uint_ret(out, matched as u64, 4);
}

