/// `ArchiveXL.ApplyVisualTagOverrideForMod(entity: wref<Entity>, tag: String, modHash: Uint64)
/// -> Int32` — round 6 (2026-08-12), item `#22`: variante MULTI-MOD de `ApplyVisualTagOverride`
/// — 2 mods diferentes (hashes diferentes) aplicando a MESMA tag no MESMO componente agora
/// COMBINAM (AND-cumulativo hiding / OR-cumulativo showing, fiel a `ComponentState` real) em
/// vez de "o último a chamar vence". Devolve a contagem de componentes efetivamente escritos.
unsafe extern "C" fn tramp_archivexl_apply_visual_tag_override_for_mod(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let func = current_native_func();
    let (args, strings) = rtti::read_params_consuming_with_strings(func, frame);
    let entity = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let tag = strings.get(1).cloned().flatten().unwrap_or_default();
    let mod_hash = args.get(2).map(|(v, _)| *v).unwrap_or(0);
    let (checked, matched, applied) = match crate::registry() {
        Some(reg) if rtti::sane(entity) => apply_visual_tag_override_for_mod(reg, entity, &tag, mod_hash, false, false),
        _ => (0, 0, 0),
    };
    crate::log(&format!(
        "[reg] >>> ArchiveXL.ApplyVisualTagOverrideForMod(entity={entity:p}, tag='{tag}', mod_hash={mod_hash:#018x}) -> checked={checked} matched={matched} applied={applied}"
    ));
    write_uint_ret(out, applied as u64, 4);
}

/// `ArchiveXL.RemoveVisualTagOverrideForMod(entity: wref<Entity>, tag: String, modHash: Uint64)
/// -> Int32` — round 6 (2026-08-12), item `#22`: contraparte de remoção — desfaz só a
/// contribuição de `mod_hash`, preservando overrides de outros mods no mesmo componente
/// (removal-safety, a regra-mãe do projeto). Se `mod_hash` era o ÚLTIMO override registrado
/// naquele componente, o `chunkMask` volta pro baseline cacheado (não fica preso num valor
/// combinado obsoleto). Devolve a contagem de componentes efetivamente REESCRITOS.
unsafe extern "C" fn tramp_archivexl_remove_visual_tag_override_for_mod(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let func = current_native_func();
    let (args, strings) = rtti::read_params_consuming_with_strings(func, frame);
    let entity = args.first().map(|(v, _)| *v as *mut c_void).unwrap_or(std::ptr::null_mut());
    let tag = strings.get(1).cloned().flatten().unwrap_or_default();
    let mod_hash = args.get(2).map(|(v, _)| *v).unwrap_or(0);
    let (with_state, removed, rewritten) = match crate::registry() {
        Some(reg) if rtti::sane(entity) => remove_visual_tag_override_for_mod(reg, entity, &tag, mod_hash, false),
        _ => (0, 0, 0),
    };
    crate::log(&format!(
        "[reg] >>> ArchiveXL.RemoveVisualTagOverrideForMod(entity={entity:p}, tag='{tag}', mod_hash={mod_hash:#018x}) -> com_estado={with_state} removidos={removed} reescritos={rewritten}"
    ));
    write_uint_ret(out, rewritten as u64, 4);
}

