pub unsafe fn register_dynamicentitysystem(reg: &Registry) -> String {
    let igs = reg.class_by_name("IGameSystem");
    let igs = if rtti::sane(igs) { igs } else { resolve_class_via_validator_getclass("IGameSystem") };
    if !rtti::sane(igs) {
        return "[reg] register_dynamicentitysystem: 'IGameSystem' não resolveu".into();
    }
    let forged = register_type_instantiable_with_parent(reg, "DynamicEntitySystem", "gameuiInGameMenuGameController", igs);
    if forged.is_null() {
        return "[reg] register_dynamicentitysystem: forja da classe FALHOU".into();
    }
    let proto = match method_donor_proto(reg) {
        Some(p) => p,
        None => return "[reg] register_dynamicentitysystem: sem protótipo de método".into(),
    };
    let m1 = register_method(reg, "DynamicEntitySystem", proto, "IsReady", "IsReady", tramp_des_is_ready, false);
    let m2 = register_method(reg, "DynamicEntitySystem", proto, "IsRestored", "IsRestored", tramp_des_is_restored, false);
    let m3 = register_method(reg, "DynamicEntitySystem", proto, "IsManaged", "IsManaged", tramp_des_is_managed, false);
    let m4 = register_method(reg, "DynamicEntitySystem", proto, "IsTagged", "IsTagged", tramp_des_is_tagged, false);
    let m5 = register_method(reg, "DynamicEntitySystem", proto, "IsPopulated", "IsPopulated", tramp_des_is_populated, false);
    let m6 = register_method(reg, "DynamicEntitySystem", proto, "AssignTag", "AssignTag", tramp_des_assign_tag, false);
    let m7 = register_method(reg, "DynamicEntitySystem", proto, "UnassignTag", "UnassignTag", tramp_des_unassign_tag, false);
    let m8 = register_method(reg, "DynamicEntitySystem", proto, "DeleteTagged", "DeleteTagged", tramp_des_delete_tagged, false);
    // Round 8 (2026-08-12): 5 getters escalares novos (`GetTaggedID`/`GetTaggedCount`/
    // `GetTaggedIDByIndex`/`GetTagCount`/`GetTagByIndex`) — mesmo idioma Count()+ByIndex(i) já
    // usado por `ReflectionClass`/`Scripting.GetStackTrace` pra evitar array-retorno.
    let m9 = register_method(reg, "DynamicEntitySystem", proto, "GetTaggedID", "GetTaggedID", tramp_des_get_tagged_id, false);
    let m10 = register_method(reg, "DynamicEntitySystem", proto, "GetTaggedCount", "GetTaggedCount", tramp_des_get_tagged_count, false);
    let m11 = register_method(reg, "DynamicEntitySystem", proto, "GetTaggedIDByIndex", "GetTaggedIDByIndex", tramp_des_get_tagged_id_by_index, false);
    let m12 = register_method(reg, "DynamicEntitySystem", proto, "GetTagCount", "GetTagCount", tramp_des_get_tag_count, false);
    let m13 = register_method(reg, "DynamicEntitySystem", proto, "GetTagByIndex", "GetTagByIndex", tramp_des_get_tag_by_index, false);
    format!(
        "[reg] DynamicEntitySystem: classe=OK (INSTANCIÁVEL, parent=IGameSystem real, mesma receita de CallbackSystem) \
IsReady={m1} IsRestored={m2} IsManaged={m3} IsTagged={m4} IsPopulated={m5} AssignTag={m6} UnassignTag={m7} DeleteTagged={m8} \
GetTaggedID={m9} GetTaggedCount={m10} GetTaggedIDByIndex={m11} GetTagCount={m12} GetTagByIndex={m13} \
— subconjunto de tag-bookkeeping (CreateEntity/GetTags/GetTaggedIDs-array/RegisterListener FORA desta rodada)"
    )
}

static DYNENT_INSTANCE: std::sync::atomic::AtomicPtr<c_void> = std::sync::atomic::AtomicPtr::new(std::ptr::null_mut());

/// `BwmsGetDynamicEntitySystem()` — GLOBAL, não `@addMethod(GameInstance)` (mesmo motivo pragmático
/// de `BwmsGetCallbackSystem`/`BwmsGetScriptableServiceContainer`: `GameInstance` valida MUITO cedo
/// no bundle, `@addMethod` direto nela já crashou o boot em 2026-07-13). Instância lazy, cacheada.
unsafe extern "C" fn tramp_get_dynamicentitysystem(_c: *mut c_void, _f: *mut c_void, out: *mut c_void, _rt: i64) {
    let mut ptr = DYNENT_INSTANCE.load(Ordering::Acquire);
    if ptr.is_null() {
        if let Some(reg) = rtti::Registry::obtain() {
            let obj = rtti::new_object(&reg, "DynamicEntitySystem");
            if !obj.is_null() {
                DYNENT_INSTANCE.store(obj, Ordering::Release);
                ptr = obj;
                crate::log(&format!("[dynent] BwmsGetDynamicEntitySystem: instância construída {obj:p} (lazy, 1a chamada)"));
            } else {
                crate::log("[dynent] BwmsGetDynamicEntitySystem: new_object('DynamicEntitySystem') falhou");
            }
        }
    }
    write_handle_ret(out, ptr as u64);
}

// ===== Codeware `#75` (`StaticEntitySystem`) — implementação NOVA, 2026-08-15 =========================
//
// Módulo IRMÃO de `DynamicEntitySystem` (#73, FECHADO acima), nunca implementado antes desta rodada
// (confirmado por grep: zero ocorrência de "StaticEntitySystem"/"tramp_ses_" neste arquivo e em
// `blackwall-mods-dev/*.reds` antes desta mudança). Fonte real: `enablers/Codeware/src/App/World/
// StaticEntitySystem.hpp`+`.cpp` (lido por completo agora) + `enablers/Codeware/scripts/World/
// StaticEntitySystem.reds` (18 métodos). Mesmo subconjunto de risco BAIXO já aplicado ao `#73`:
// tag-bookkeeping puro (registry Rust-side, `HashMap<u64,HashSet<u64>>`, zero ponteiro de Entity,
// zero endereço nativo) — `IsManaged`/`IsTagged`/`AssignTag`/`UnassignTag`/`IsPopulated` (o C++ real,
// linhas 244-417, é literalmente `std::shared_lock`/`scoped_lock` sobre `Core::Map<EntityID,Set<CName>>`
// + o espelho `Core::Map<CName,Set<EntityID>>` — o MESMO par de mapas já portado pro `#73`).
//
// Divergência de escopo, idêntica à já documentada pro `#73` (mesma linha de raciocínio, não repetida
// aqui por completo — ver comentário do bloco `DynamicEntitySystem` acima): `SpawnEntity`/
// `DespawnEntity`/`AttachEntity`/`DetachEntity`/`IsSpawned`/`IsSpawning`/`GetEntity`/`GetTags`/
// `GetTagged`/`DespawnTagged`/`AttachTagged`/`DetachTagged` ficam FORA — os 4 primeiros precisam de
// `EntitySpawner`/`IDynamicEntityIDSystem` reais (ausentes no BWMS); os últimos 3 são bulk-lifecycle
// que dispararia efeito FALSO sem spawn real por trás (mesmo anti-padrão já corrigido em `#79`/`#138`/
// `#139`); `GetTags`/`GetTagged` precisam de `array<T>` de retorno (categoria que já crashou 2x no
// projeto sem donor real). `IsManaged` segue a MESMA aproximação do `#73`: "já foi tagueada alguma vez"
// (a fonte real também checa `m_tokens`, que só populamos via spawn real — sempre vazio aqui).
//
// `#75` NÃO tem `IsRestored` nem `DeleteTagged` na API real (diferença genuína vs `#73`, confirmado
// lendo o header — `StaticEntitySystem.hpp` não declara nenhum dos dois) — não inventados aqui.
// Idioma "Count()+ByIndex(i)" (5 getters escalares) reusa a MESMA disciplina anti-array-retorno já
// estabelecida pro `#73`/round 8, `ReflectionClass`, `Scripting.GetStackTrace`.
type StatentMap = std::sync::Mutex<std::collections::HashMap<u64, std::collections::HashSet<u64>>>;
static STATENT_TAGS_CELL: std::sync::OnceLock<StatentMap> = std::sync::OnceLock::new();
static STATENT_BY_TAG_CELL: std::sync::OnceLock<StatentMap> = std::sync::OnceLock::new();
fn statent_tags() -> &'static StatentMap {
    STATENT_TAGS_CELL.get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
}
fn statent_by_tag() -> &'static StatentMap {
    STATENT_BY_TAG_CELL.get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
}

unsafe extern "C" fn tramp_ses_is_ready(_c: *mut c_void, _f: *mut c_void, out: *mut c_void, _rt: i64) {
    write_bool_ret(out, true);
}
unsafe extern "C" fn tramp_ses_is_managed(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let func = current_native_func();
    let args = rtti::read_params_consuming(func, frame);
    let id = args.first().map(|(v, _)| *v).unwrap_or(0);
    let v = statent_tags().lock().map(|m| m.contains_key(&id)).unwrap_or(false);
    write_bool_ret(out, v);
}
unsafe extern "C" fn tramp_ses_is_tagged(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let func = current_native_func();
    let args = rtti::read_params_consuming(func, frame);
    let id = args.first().map(|(v, _)| *v).unwrap_or(0);
    let tag = args.get(1).map(|(v, _)| *v).unwrap_or(0);
    let v = statent_tags().lock().map(|m| m.get(&id).is_some_and(|s| s.contains(&tag))).unwrap_or(false);
    write_bool_ret(out, v);
}
unsafe extern "C" fn tramp_ses_is_populated(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let func = current_native_func();
    let args = rtti::read_params_consuming(func, frame);
    let tag = args.first().map(|(v, _)| *v).unwrap_or(0);
    let v = statent_by_tag().lock().map(|m| m.get(&tag).is_some_and(|s| !s.is_empty())).unwrap_or(false);
    write_bool_ret(out, v);
}
unsafe extern "C" fn tramp_ses_assign_tag(_c: *mut c_void, frame: *mut c_void, _out: *mut c_void, _rt: i64) {
    let func = current_native_func();
    let args = rtti::read_params_consuming(func, frame);
    let id = args.first().map(|(v, _)| *v).unwrap_or(0);
    let tag = args.get(1).map(|(v, _)| *v).unwrap_or(0);
    if let Ok(mut m) = statent_tags().lock() {
        m.entry(id).or_default().insert(tag);
    }
    if let Ok(mut m) = statent_by_tag().lock() {
        m.entry(tag).or_default().insert(id);
    }
    crate::log(&format!("[statent] AssignTag id={id:#x} tag={tag:#x} ({})", crate::cname::resolve_cname(tag)));
}
unsafe extern "C" fn tramp_ses_unassign_tag(_c: *mut c_void, frame: *mut c_void, _out: *mut c_void, _rt: i64) {
    let func = current_native_func();
    let args = rtti::read_params_consuming(func, frame);
    let id = args.first().map(|(v, _)| *v).unwrap_or(0);
    let tag = args.get(1).map(|(v, _)| *v).unwrap_or(0);
    if let Ok(mut m) = statent_tags().lock() {
        if let Some(s) = m.get_mut(&id) {
            s.remove(&tag);
        }
    }
    if let Ok(mut m) = statent_by_tag().lock() {
        if let Some(s) = m.get_mut(&tag) {
            s.remove(&id);
        }
    }
    crate::log(&format!("[statent] UnassignTag id={id:#x} tag={tag:#x}"));
}

/// Núcleos puros: idênticos aos já testados/provados de `dynent_pick_tagged_id`/`dynent_tagged_count`/
/// `dynent_tagged_id_by_index`/`dynent_tag_count`/`dynent_tag_by_index` (item `#73`) — reusar a MESMA
/// função geraria confusão entre os 2 registries (Static≠Dynamic são estados independentes na fonte
/// real), então duplicados com nome próprio em vez de compartilhados.
fn statent_pick_tagged_id(m: &std::collections::HashMap<u64, std::collections::HashSet<u64>>, tag: u64) -> u64 {
    m.get(&tag).and_then(|s| s.iter().min().copied()).unwrap_or(0)
}
fn statent_tagged_count(m: &std::collections::HashMap<u64, std::collections::HashSet<u64>>, tag: u64) -> i32 {
    m.get(&tag).map(|s| s.len() as i32).unwrap_or(0)
}
fn statent_tagged_id_by_index(m: &std::collections::HashMap<u64, std::collections::HashSet<u64>>, tag: u64, idx: i32) -> u64 {
    if idx < 0 {
        return 0;
    }
    match m.get(&tag) {
        Some(s) => {
            let mut v: Vec<u64> = s.iter().copied().collect();
            v.sort_unstable();
            v.get(idx as usize).copied().unwrap_or(0)
        }
        None => 0,
    }
}
fn statent_tag_count(m: &std::collections::HashMap<u64, std::collections::HashSet<u64>>, id: u64) -> i32 {
    m.get(&id).map(|s| s.len() as i32).unwrap_or(0)
}
fn statent_tag_by_index(m: &std::collections::HashMap<u64, std::collections::HashSet<u64>>, id: u64, idx: i32) -> u64 {
    if idx < 0 {
        return 0;
    }
    match m.get(&id) {
        Some(s) => {
            let mut v: Vec<u64> = s.iter().copied().collect();
            v.sort_unstable();
            v.get(idx as usize).copied().unwrap_or(0)
        }
        None => 0,
    }
}

unsafe extern "C" fn tramp_ses_get_tagged_id(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let func = current_native_func();
    let args = rtti::read_params_consuming(func, frame);
    let tag = args.first().map(|(v, _)| *v).unwrap_or(0);
    let id = statent_by_tag().lock().map(|m| statent_pick_tagged_id(&m, tag)).unwrap_or(0);
    write_uint_ret(out, id, 8);
}
