/// Versão que reportamos como "ArchiveXL compatível" (2026-08-05, achado de auditoria: `App::
/// Facade` real do ArchiveXL — `enablers/ArchiveXL/src/App/Facade.hpp` — tem `Version`/`Require`/
/// `Reload`/`RegisterDir`/`RegisterArchive`/`GetBodyType`/`EnableGarmentOffsets`/
/// `DisableGarmentOffsets`, NENHUM portado apesar do catálogo "28/28 IMPL". Aqui só `Version`/
/// `Require` — os outros precisam de backing funcional real, não são smoke de facade). Sem
/// changelog/CMake com versão real no vendorizado — `1.0.0` conservador, mesmo critério do
/// TweakXL.
const ARCHIVEXL_VERSION: &str = "1.0.0";

unsafe extern "C" fn tramp_archivexl_version(_c: *mut c_void, _f: *mut c_void, out: *mut c_void, _rt: i64) {
    crate::log("[reg] >>> ArchiveXL.Version chamado");
    if !out.is_null() {
        std::ptr::write_bytes(out as *mut u8, 0, 0x20);
        rtti::red_string_write_inline(out as *mut u8, ARCHIVEXL_VERSION);
    }
}

unsafe extern "C" fn tramp_archivexl_require(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let func = current_native_func();
    let (_args, strings) = rtti::read_params_consuming_with_strings(func, frame);
    let requested = strings.first().cloned().flatten().unwrap_or_default();
    let ok = crate::api::semver_precedence(ARCHIVEXL_VERSION, &requested) != std::cmp::Ordering::Less;
    crate::log(&format!("[reg] >>> ArchiveXL.Require('{requested}') vs nosso '{ARCHIVEXL_VERSION}' -> {ok}"));
    write_bool_ret(out, ok);
}

