/// ArchiveXL `#27`, metade leitura: `GetAliasCount(path) -> Int32` — quantos paths foram
/// registrados (via `RegisterLink`/`resource.link`) apontando PRA `path` (o canônico). Composto
/// com `GetAliasHash` abaixo pra enumerar sem precisar de um `array<T>`-retorno-de-native (a
/// categoria de risco que já CROU este projeto — `TweakXL #43`/`GetRecordsArray`, 2026-08-10 —
/// evitada de propósito aqui: 2 natives escalares em vez de 1 native com array de saída).
unsafe extern "C" fn tramp_archivexl_get_alias_count(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let func = current_native_func();
    let (_args, strings) = rtti::read_params_consuming_with_strings(func, frame);
    let path = strings.first().cloned().flatten().unwrap_or_default();
    let hash = bwms_hashes::resource_path_hash(&path);
    let n = crate::selftest::reslink_aliases_of(hash).len();
    crate::log(&format!("[reg] >>> ArchiveXL.GetAliasCount('{path}') -> {n}"));
    write_uint_ret(out, n as u64, 4);
}

/// ArchiveXL `#27`, `GetAliasHash(path, index) -> Uint64` — devolve o HASH (não o path decodificado
/// — `ResourcePath` é hash-only, mesma divergência já aceita em `BwmsHashToResRef`/etc.) do
/// alias no índice `index` (0-based) dentre os registrados pra `path`. `index` fora do alcance
/// devolve `0`.
unsafe extern "C" fn tramp_archivexl_get_alias_hash(_c: *mut c_void, frame: *mut c_void, out: *mut c_void, _rt: i64) {
    let func = current_native_func();
    let (args, strings) = rtti::read_params_consuming_with_strings(func, frame);
    let path = strings.first().cloned().flatten().unwrap_or_default();
    let index = args.get(1).map(|(v, _)| *v as i32).unwrap_or(0);
    let hash = bwms_hashes::resource_path_hash(&path);
    let aliases = crate::selftest::reslink_aliases_of(hash);
    let v = if index >= 0 { aliases.get(index as usize).copied().unwrap_or(0) } else { 0 };
    crate::log(&format!("[reg] >>> ArchiveXL.GetAliasHash('{path}', {index}) -> {v:#018x}"));
    write_uint_ret(out, v, 8);
}

